function lessonReferences(l){return (l.tables||[]).map(t=>`<div class="lesson-table-wrap"><table class="lesson-table"><caption>${esc(t.caption)}</caption><thead><tr>${t.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')+(l.refs?.length?`<aside class="notice small"><b>Quellen · geprüft am 4. Oktober 2026</b><ul>${l.refs.map(([label,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a></li>`).join('')}</ul></aside>`:'');}
function questionType(q){return ['q11','q12'].includes(q.id)?'image':'text'}
function shuffled(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function balancedQuestions(pool,count){const buckets=shuffled(TOPICS).map(t=>shuffled(pool.filter(q=>q.topic===t))).filter(b=>b.length);const chosen=[];while(chosen.length<Math.min(count,pool.length)){for(const bucket of buckets){if(bucket.length&&chosen.length<count)chosen.push(bucket.pop())}}return shuffled(chosen)}
function studyChecklist(){const p=state.data.progress;return `<section class="card" style="margin-top:1rem"><h2>Dein Prüfungslernplan</h2><p class="muted">Arbeite die Themen durch und wiederhole die Erklärungen zu falschen Antworten. Die Übersicht zeigt deinen Lernstand.</p><div class="lesson-list">${TOPICS.map(t=>{const ls=lessons.filter(l=>l.topic===t);const done=ls.filter(l=>p.lessons.includes(l.id)).length;const q=p.topic?.[t]||{answered:0,correct:0};return `<div class="lesson-item"><div><b>${esc(t)}</b><small>${done}/${ls.length} Lektionen · ${q.answered} Antworten · ${q.answered?pct(q.correct,q.answered)+' % richtig':'noch nicht geübt'}</small></div><button class="btn secondary smallbtn" data-lesson="${(ls.find(l=>!p.lessons.includes(l.id))||ls[0]).id}">Weiterlernen</button></div>`}).join('')}</div><p><button class="btn secondary" data-lesson="exam-rehearsal">Abschlussfall gemeinsam durchgehen</button></p><p class="small muted">Zum Abschluss: gemischte Übungsprüfung, offene Fehler und Praxis-Checkliste bearbeiten. Besprich die Anforderungen deiner Prüfung und das Betriebsgerät mit deiner ausbildenden Person.</p><button class="btn primary" data-go="examSetup">Gemischte Prüfung vorbereiten</button></section>`}
function calculateMfa(method,s,f){return method==='zp'?58.10122-.56495*s+.13199*f:60.98501-.85831*s+.16449*f}
function mfaClass(value){return value>=60?'S':value>=55?'E':value>=50?'U':value>=45?'R':value>=40?'O':'P'}
function calculatorView(el){let curMethod='zp',curS=16.0,curF=60.0;function renderCalc(){const val=calculateMfa(curMethod,curS,curF);const cls=mfaClass(val);const clsClass='grade-'+cls.toLowerCase();const fmt=n=>n.toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:2});const fmtFull=n=>n.toLocaleString('de-DE',{maximumFractionDigits:5});const fatH=Math.max(16,Math.min(76,Math.round(curS*1.85)));const muscleH=Math.max(38,Math.min(110,Math.round(curF*1.22)));const skinH=10,skinY=28,fatY=skinY+skinH,muscleY=fatY+fatH,boneY=muscleY+muscleH,probeDepth=fatY+fatH+Math.round(muscleH*0.65);el.innerHTML=head('Rechnen üben','MFA-Rechenwerkstatt & Carcass-Simulator','Interaktive Querschnitt-Simulation und Formelberechnung nach SchwHKlV.')+`<div class="preset-pills"><span class="small muted" style="align-self:center">Klassen-Presets:</span><button class="btn ghost smallbtn" data-preset="s">Klasse S (12/65 mm)</button><button class="btn ghost smallbtn" data-preset="e">Klasse E (16/60 mm)</button><button class="btn ghost smallbtn" data-preset="u">Klasse U (20/55 mm)</button><button class="btn ghost smallbtn" data-preset="r">Klasse R (26/50 mm)</button><button class="btn ghost smallbtn" data-preset="o">Klasse O (32/45 mm)</button><button class="btn ghost smallbtn" data-preset="p">Klasse P (38/40 mm)</button></div><section class="carcass-simulator"><div class="simulator-header"><div><span class="eyebrow">${curMethod==='zp'?'Zweipunktverfahren (Anlage 3)':'Sondengeräte / OptiGrade (Anlage 2)'}</span><h2 style="margin:0">${fmt(val)} % Muskelfleischanteil</h2><span class="muted small">${val>=60?'Sehr hoher Fleischanteil':val>=55?'Standard-Handelsklasse':'Geringerer Fleischanteil'}</span></div><div class="grade-badge-large ${clsClass}"><span>${cls}</span><small>KLASSE</small></div></div><div class="simulator-svg-wrap"><svg class="simulator-svg" viewBox="0 0 680 230" aria-label="Schlachtkörper-Querschnitt"><line x1="50" y1="18" x2="630" y2="18" stroke="#cdd8dc" stroke-width="1"/><text x="50" y="14" font-size="10" fill="#657783">0 mm (Außenhaut)</text><text x="630" y="14" font-size="10" fill="#657783" text-anchor="end">Schnitt-Achse</text><rect x="50" y="${skinY}" width="460" height="${skinH}" fill="#E8B89E" rx="2"/><text x="60" y="${skinY+8}" font-size="9" font-weight="700" fill="#5A3525">SCHWARTE</text><rect x="50" y="${fatY}" width="460" height="${fatH}" fill="#FFF8EE" stroke="#EFE4D0" stroke-width="1"/><text x="60" y="${fatY+Math.min(fatH-4,16)}" font-size="11" font-weight="700" fill="#8B6F38">RÜCKENSPECK (S = ${fmt(curS)} mm)</text><rect x="50" y="${muscleY}" width="460" height="${muscleH}" fill="#C95454" stroke="#B04040" stroke-width="1"/><text x="60" y="${muscleY+18}" font-size="11" font-weight="700" fill="#FFFFFF">M. LONGISSIMUS DORSI (F = ${fmt(curF)} mm)</text><rect x="50" y="${boneY}" width="460" height="24" fill="#E2E7EA" rx="2"/><text x="60" y="${boneY+16}" font-size="10" font-weight="700" fill="#5F707A">WIRBELKANAL / RIPPENKANTE</text><rect x="360" y="4" width="16" height="${probeDepth}" fill="#90A4AE" rx="2"/><rect x="364" y="4" width="8" height="${probeDepth}" fill="#CFD8DC"/><polygon points="360,${probeDepth} 376,${probeDepth} 368,${probeDepth+14}" fill="#455A64"/><circle cx="368" cy="${fatY+fatH}" r="4" fill="#00E5FF"/><text x="382" y="${probeDepth+8}" font-size="10" font-weight="700" fill="#37474F">Sonde</text><g transform="translate(530, 25)"><rect x="0" y="0" width="110" height="180" fill="#FFFFFF" stroke="#E1E8EB" rx="8"/><text x="55" y="16" font-size="9" font-weight="700" fill="#17344B" text-anchor="middle">Reflexionsprofil</text><path d="M 15,${Math.max(25,fatY-15)} L 90,${fatY} L 90,${fatY+fatH-5} L 25,${muscleY+10} L 25,${muscleY+muscleH-5} L 75,${boneY}" fill="none" stroke="#087E83" stroke-width="2.5"/><text x="92" y="${fatY+(fatH/2)}" font-size="8" fill="#8B6F38">Fett</text><text x="15" y="${muscleY+(muscleH/2)}" font-size="8" fill="#C95454">Muskel</text></g></svg></div><div class="formula-callout"><code>${curMethod==='zp'?'58,10122 − 0,56495 × S + 0,13199 × F':'60,98501 − 0,85831 × S + 0,16449 × F'}</code><div class="small" style="margin-top:.35rem">${curMethod==='zp'?'58,10122':'60,98501'} − (0,${curMethod==='zp'?'56495':'85831'} × ${fmt(curS)}) + (0,${curMethod==='zp'?'13199':'16449'} × ${fmt(curF)}) = <b>${fmtFull(val)} %</b></div></div><div class="sim-sliders"><div class="sim-slider-row"><div class="sim-slider-header"><label for="sim-s">S · Rückenspeck einschl. Schwarte</label><span id="sim-s-val">${fmt(curS)} mm</span></div><input type="range" class="sim-range" id="sim-s" min="4" max="45" step="0.5" value="${curS}"></div><div class="sim-slider-row"><div class="sim-slider-header"><label for="sim-f">F · Fleischmaß (M. longissimus dorsi)</label><span id="sim-f-val">${fmt(curF)} mm</span></div><input type="range" class="sim-range" id="sim-f" min="20" max="100" step="0.5" value="${curF}"></div></div><div class="row between" style="margin-top:1.2rem"><div class="field" style="margin:0;min-width:240px"><label for="sim-method">Verfahren wählen</label><select id="sim-method"><option value="zp" ${curMethod==='zp'?'selected':''}>ZP-Verfahren (SchwHKlV Anlage 3)</option><option value="probe" ${curMethod==='probe'?'selected':''}>Sondengeräte / OptiGrade (Anlage 2)</option></select></div><button class="btn secondary" id="toggle-f-star" style="align-self:flex-end">F*-Umrechnung (G-Maß)</button></div><div id="f-star-box" class="notice small hide" style="margin-top:1rem"><b>Ersatzfleischmaß F* nach SchwHKlV Anlage 2:</b><p>Wird am Gerät die Gesamtdicke G erfasst: <code>F* = 0,95 × G − 3</code>.</p><div class="row"><input type="number" id="input-g" placeholder="G in mm (z. B. 66)" style="max-width:200px"><button class="btn primary smallbtn" id="apply-g">F* berechnen & übernehmen</button></div></div></section><section class="card" style="margin-top:1rem"><h2>Praxis-Rechenbeispiele zum Nachrechnen</h2><div class="grid three"><article class="card tight"><b>Beispiel 1 (ZP)</b><p class="small muted">S = 20 mm, F = 60 mm</p><span class="tag">54,72 % · Klasse U</span></article><article class="card tight"><b>Beispiel 2 (ZP)</b><p class="small muted">S = 10 mm, F = 70 mm</p><span class="tag">61,69 % · Klasse S</span></article><article class="card tight"><b>Beispiel 3 (Sonde)</b><p class="small muted">S = 16 mm, F = 60 mm</p><span class="tag">57,12 % · Klasse E</span></article></div><div class="row" style="margin-top:1rem"><button class="btn secondary" data-route="cheatsheet">⚡ Formeln im Spickzettel</button><button class="btn secondary" data-go="practice">Rechenfragen üben</button></div></section>`;el.querySelector('#sim-s').oninput=e=>{curS=Number(e.target.value);renderCalc()};el.querySelector('#sim-f').oninput=e=>{curF=Number(e.target.value);renderCalc()};el.querySelector('#sim-method').onchange=e=>{curMethod=e.target.value;renderCalc()};el.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const p=b.dataset.preset;if(p==='s'){curS=12;curF=65;}else if(p==='e'){curS=16;curF=60;}else if(p==='u'){curS=20;curF=55;}else if(p==='r'){curS=26;curF=50;}else if(p==='o'){curS=32;curF=45;}else if(p==='p'){curS=38;curF=40;}renderCalc()});const fStarBox=el.querySelector('#f-star-box');el.querySelector('#toggle-f-star').onclick=()=>fStarBox.classList.toggle('hide');el.querySelector('#apply-g')?.addEventListener('click',()=>{const g=Number(el.querySelector('#input-g').value);if(g>0){curF=Math.round((0.95*g-3)*10)/10;curMethod='probe';renderCalc();toast(`F* = ${curF} mm übernommen`)}});bindGo(el)};renderCalc();}
function dueCards(all,records,date){return all.filter(c=>!records?.[c[0]]?.due||records[c[0]].due<=date)}
const state={role:null,route:'home',data:null,trainer:null,filter:'Alle Themen',practice:null,exam:null,selected:null,feedback:false,flashIndex:0,flashRevealed:false,trainerLearner:null,trainerSearch:'',lesson:null,lessonEnglish:false,toastTimer:null,isOffline:false,cheatsheetSearch:'',mediathekTab:'autofom'};
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const today=()=>new Date().toISOString().slice(0,10);
function applyLocalEvent(b){if(!state.data?.progress)return;const p=state.data.progress;const todayStr=today();p.lastActive='Heute';if(b.type==='answer'){p.answered++;if(b.correct)p.correct++;p.daily[todayStr]=(p.daily[todayStr]||0)+1;const t=b.topic||'Grundlagen';p.topic[t]||={answered:0,correct:0};p.topic[t].answered++;if(b.correct)p.topic[t].correct++;if(!b.correct&&b.questionId&&!p.mistakes.some(m=>m.id===b.questionId))p.mistakes.unshift({id:b.questionId,at:todayStr,topic:t});if(b.correct&&b.questionId)p.mistakes=p.mistakes.filter(m=>m.id!==b.questionId);p.history.push({date:todayStr,type:'answer',correct:!!b.correct});}else if(b.type==='lesson'&&b.lessonId&&!p.lessons.includes(b.lessonId)){p.lessons.push(b.lessonId);}else if(b.type==='bookmark'){p.bookmarks=p.bookmarks.includes(b.questionId)?p.bookmarks.filter(x=>x!==b.questionId):[b.questionId,...p.bookmarks];}else if(b.type==='mistakeCleared'){p.mistakes=p.mistakes.filter(m=>m.id!==b.questionId);}else if(b.type==='card'){const c=p.cards[b.cardId]||{repetitions:0,due:todayStr};c.repetitions++;c.due=new Date(Date.now()+(b.confidence==='easy'?3:b.confidence==='hard'?0:1)*86400000).toISOString().slice(0,10);p.cards[b.cardId]=c;}try{localStorage.setItem('kk_cached_state',JSON.stringify(state.data))}catch{}}
async function syncOfflineQueue(){const raw=typeof localStorage!=='undefined'&&localStorage.getItem('kk_offline_queue');if(!raw)return;let queue=[];try{queue=JSON.parse(raw)}catch{return}if(!queue.length)return;let item;while((item=queue.shift())){try{await fetch('/api'+item.url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item.payload)})}catch{}}localStorage.removeItem('kk_offline_queue');state.isOffline=false;toast('Offline-Aktivitäten synchronisiert');try{await refresh();render()}catch{}}
if(typeof window!=='undefined')window.addEventListener('online',syncOfflineQueue);
const api=async(url,method='GET',payload)=>{try{const r=await fetch('/api'+url,{method,headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Aktion fehlgeschlagen.');if(url==='/state'&&method==='GET'){try{localStorage.setItem('kk_cached_state',JSON.stringify(d));state.isOffline=false}catch{}}return d}catch(err){if(typeof window!=='undefined'&&(!navigator.onLine||err.message==='Failed to fetch'||err.name==='TypeError'||err.message?.includes('fetch'))){state.isOffline=true;if(url==='/state'&&method==='GET'){const cached=localStorage.getItem('kk_cached_state');if(cached){return JSON.parse(cached)}const init={name:'Lernende/r',role:'learner',group:'Lokales Lernen',demo:true,settings:{goal:15,examDate:'',fontScale:1,language:'de'},progress:{answered:0,correct:0,lessons:[],streak:0,lastActive:'Heute',daily:{},topic:{},bookmarks:[],mistakes:[],cards:{},practical:[],history:[]}};try{localStorage.setItem('kk_cached_state',JSON.stringify(init))}catch{}return init;}if(url==='/demo-login'&&method==='POST'){const role=payload?.role||'learner';const dState={name:role==='trainer'?'Ausbilder (Lokal)':'Lernende/r (Lokal)',role,group:'Lerngruppe A',demo:true,settings:{goal:15,examDate:'',fontScale:1,language:'de'},progress:{answered:0,correct:0,lessons:[],streak:0,lastActive:'Heute',daily:{},topic:{},bookmarks:[],mistakes:[],cards:{},practical:[],history:[]}};try{localStorage.setItem('kk_cached_state',JSON.stringify(dState))}catch{}return dState;}if(url==='/auth/login'||url==='/auth/register'){const name=payload?.name||(payload?.email?payload.email.split('@')[0]:'Lernende/r');const role=payload?.role||'learner';const uState={name,role,group:payload?.group||'Lokale Gruppe',demo:false,settings:{goal:15,examDate:'',fontScale:1,language:'de'},progress:{answered:0,correct:0,lessons:[],streak:0,lastActive:'Heute',daily:{},topic:{},bookmarks:[],mistakes:[],cards:{},practical:[],history:[]}};try{localStorage.setItem('kk_cached_state',JSON.stringify(uState))}catch{}return uState;}if(url==='/logout'&&method==='POST'){try{localStorage.removeItem('kk_cached_state')}catch{}return {ok:true};}if(url==='/event'&&method==='POST'){try{const q=JSON.parse(localStorage.getItem('kk_offline_queue')||'[]');q.push({url,payload,at:Date.now()});localStorage.setItem('kk_offline_queue',JSON.stringify(q))}catch{}applyLocalEvent(payload);return {progress:state.data?.progress,offline:true};}}throw err}};
function speak(text){if(typeof window!=='undefined'&&window.speechSynthesis){try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=0.92;window.speechSynthesis.speak(u)}catch{}}}
function getTheme(){return localStorage.getItem('kk_theme')||(typeof window!=='undefined'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}
function applyTheme(t){if(typeof document!=='undefined'){document.documentElement.setAttribute('data-theme',t);localStorage.setItem('kk_theme',t)}}
function toggleTheme(){const next=getTheme()==='dark'?'light':'dark';applyTheme(next);render()}
