function toast(s){const old=document.querySelector('.toast');if(old)old.remove();const e=document.createElement('div');e.className='toast';e.textContent=s;document.body.append(e);clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>e.remove(),2600)}
function setFont(){document.documentElement.style.setProperty('--fs',String(state.data?.settings?.fontScale||1))}
function initialView(){const hash=typeof window!=='undefined'?window.location.hash:'';const isInvite=hash.startsWith('#invite=');app.innerHTML=`<main class="auth-wrap"><section class="card auth-card"><div class="auth-brand"><img src="/icon.svg" alt=""><h1>Klassenklar</h1><p class="muted">Schweineklassifizierung verständlich lernen</p></div><div class="notice small">Lern-App für die Prüfungsvorbereitung. Übungsprüfungen sind <b>keine offiziellen Prüfungen</b>.</div><div class="auth-tabs"><button class="${isInvite?'':'active'}" data-auth-tab="login">Anmelden</button><button class="${isInvite?'active':''}" data-auth-tab="register">Konto erstellen</button></div><div id="auth-form"></div><div class="divider"><p class="eyebrow">Direkt ausprobieren</p><p class="small muted">Demo-Zugänge sind für eine lokale Vorschau. Die Demo-Daten sind beispielhaft.</p><div class="grid two"><button class="btn secondary" data-demo="learner">Demo: Lernen</button><button class="btn secondary" data-demo="trainer">Demo: Ausbilden</button></div></div><p class="small muted">Konten werden lokal auf diesem Gerät gespeichert. Für den produktiven Einsatz sind Hosting, HTTPS, Backups und Datenschutzkonzept erforderlich.</p></section></main>`; renderAuthForm(isInvite?'register':'login');app.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{app.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));renderAuthForm(b.dataset.authTab)});app.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>enterDemo(b.dataset.demo));}
function renderAuthForm(mode){const host=document.querySelector('#auth-form');if(!host)return;const register=mode==='register';host.innerHTML=register?`<form id="auth-action"><div class="field"><label for="auth-name">Name</label><input id="auth-name" name="name" required minlength="2" autocomplete="name"></div><div class="field"><label for="auth-email">E-Mail</label><input id="auth-email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="auth-password">Passwort (mindestens 10 Zeichen)</label><input id="auth-password" name="password" type="password" required minlength="10" autocomplete="new-password"></div><div class="field"><label for="auth-role">Ich bin …</label><select id="auth-role" name="role"><option value="learner">Lernende/r</option><option value="trainer">Ausbilder/in</option></select></div><div id="group-field" class="field"><label for="auth-group">Name der eigenen Lerngruppe</label><input id="auth-group" name="group" placeholder="z. B. Ausbildung 2026" required></div><div id="invite-field" class="field hide"><label for="auth-invite">Einladungscode (optional)</label><input id="auth-invite" name="inviteCode" autocomplete="off"><small>Mit Code wirst du der Lerngruppe des Ausbilders zugeordnet.</small></div><button class="btn primary full">Konto erstellen</button><div id="auth-error"></div></form>`:`<form id="auth-action"><div class="field"><label for="auth-email">E-Mail</label><input id="auth-email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="auth-password">Passwort</label><input id="auth-password" name="password" type="password" required autocomplete="current-password"></div><button class="btn primary full">Anmelden</button><div id="auth-error"></div></form>`;
 const form=host.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form));try{await api(register?'/auth/register':'/auth/login','POST',b);await enterApp();}catch(err){host.querySelector('#auth-error').innerHTML=`<div class="notice error small">${esc(err.message)}</div>`;}};
 if(register){const role=form.elements.role;const sync=()=>{const trainer=role.value==='trainer';form.querySelector('#group-field').classList.toggle('hide',!trainer);form.querySelector('#invite-field').classList.toggle('hide',trainer);form.elements.group.required=trainer};role.onchange=sync;sync();if(typeof window!=='undefined'&&window.location.hash.startsWith('#invite=')){const code=window.location.hash.slice(8).trim().toUpperCase();if(form.elements.inviteCode)form.elements.inviteCode.value=code;}}}
async function enterDemo(role){try{await api('/demo-login','POST',{role});await enterApp()}catch(e){toast(e.message)}}
async function enterApp(){try{state.data=await api('/state');state.role=state.data.role;state.route=state.role==='trainer'?'trainer':'home';setFont();render()}catch{initialView()}}
async function logout(){await api('/logout','POST');state.role=null;state.data=null;state.trainer=null;initialView()}
function nav(){const learner=[['home','⌂','Start'],['topics','▤','Lernen'],['mediathek','🎬','Geräte'],['practice','↻','Üben'],['progress','↗','Fortschritt'],['more','•••','Mehr']];const trainer=[['trainer','◉','Übersicht'],['learners','♙','Lernende'],['results','▥','Ergebnisse'],['more','•••','Mehr']];const items=state.role==='trainer'?trainer:learner;return `<aside class="sidebar">${items.map(([id,i,n])=>`<button class="nav-btn ${state.route===id?'active':''}" data-route="${id}"><span class="nav-icon">${i}</span>${n}</button>`).join('')}<div class="sidebar-foot small muted">${state.data?.demo?'Demo-Modus':'Lokales Konto'}<br>Klassenklar · Version 2.0</div></aside><nav class="mobile-nav">${items.map(([id,i,n])=>`<button class="nav-btn ${state.route===id?'active':''}" data-route="${id}"><span class="nav-icon">${i}</span>${n}</button>`).join('')}</nav>`}
function render(){if(!state.data){initialView();return}setFont();const title=state.role==='trainer'?'Ausbilderbereich':'Schweineklassifizierung';const offlineBanner=state.isOffline?`<div class="offline-banner"><span class="offline-indicator"></span><span>Offline-Modus · Antworten werden lokal gesichert und bei Netzverbindung automatisch synchronisiert.</span></div>`:'';app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><img src="/icon.svg" alt=""><div>Klassenklar<small>${title}</small></div></div><div class="top-actions">${state.isOffline?'<span class="tag gold">Offline</span>':''}<button class="btn ghost smallbtn" id="theme-btn" title="Design wechseln">${getTheme()==='dark'?'☀️':'🌙'}</button><span class="user-name small muted">${esc(state.data.name)}${state.data.demo?' · Demo':''}</span><button class="btn ghost smallbtn" id="logout">Abmelden</button></div></header><div class="shell-body">${nav()}<main class="main" id="main">${offlineBanner}</main></div></div>`;app.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;state.selected=null;state.feedback=false;render()});document.querySelector('#logout').onclick=logout;document.querySelector('#theme-btn')?.addEventListener('click',toggleTheme);const host=document.querySelector('#main');({home:homeView,topics:topicsView,mediathek:mediathekView,lesson:lessonView,practice:practiceView,quiz:quizView,practiceResult:practiceResultView,flashcards:flashView,examSetup:examSetupView,exam:examView,examResult:examResultView,mistakes:mistakesView,progress:progressView,settings:settingsView,sources:sourcesView,calculator:calculatorView,cheatsheet:cheatsheetView,more:moreView,trainer:trainerView,learners:trainerView,results:trainerView,learnerDetail:trainerDetailView})[state.route]?.(host);}
function head(kicker,title,subtitle=''){return `<div class="section-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div></div>`}
function totalToday(){return state.data.progress.daily?.[today()]||0}
function weeklyChart(){const p=state.data.progress;return `<div class="bar-chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toISOString().slice(0,10);const n=p.daily?.[key]||0;const h=n?Math.min(100,Math.max(7,n/(state.data.settings.goal||15)*100)):4;return `<div class="bar-col"><div class="bar ${i===6?'today':''}" style="height:${h}%" title="${n} Fragen"></div><span>${['So','Mo','Di','Mi','Do','Fr','Sa'][d.getDay()]}</span></div>`}).join('')}</div>`}
function homeView(el){const p=state.data.progress;const todayN=totalToday();const next=lessons.find(l=>!p.lessons.includes(l.id))||lessons[1];const review=p.mistakes?.length||0;el.innerHTML=`<div class="section-head"><div><div class="eyebrow">Dein Lernplatz</div><h1>Hallo${state.data.name?' '+esc(state.data.name.split(' ')[0]):''} 👋</h1><p>Lerne Schritt für Schritt für die Schweineklassifizierung.</p></div></div><section class="card hero"><div class="row between"><div><div class="eyebrow" style="color:#d7eeee">Tagesziel</div><h2>${todayN} von ${state.data.settings.goal} Fragen</h2><p class="muted">${todayN>=state.data.settings.goal?'Ziel erreicht – stark!':'Jede Frage bringt dich ein Stück weiter.'}</p></div><div class="metric" style="color:white">${Math.min(100,pct(todayN,state.data.settings.goal))}%</div></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,pct(todayN,state.data.settings.goal))}%"></div></div><button class="btn secondary" style="margin-top:1rem" data-go="practice">Weiter üben</button></section><div class="grid three" style="margin-top:1rem"><article class="card"><div class="metric">${p.lessons.length}/${lessons.length}</div><div class="metric-label">Lektionen abgeschlossen</div></article><article class="card"><div class="metric">${pct(p.correct,p.answered)}%</div><div class="metric-label">Antwortgenauigkeit · ${p.answered} Antworten</div></article><article class="card"><div class="metric">${review}</div><div class="metric-label">Offene Fehler zum Wiederholen</div></article></div><section class="grid two" style="margin-top:1rem"><article class="card"><div class="row between"><div><div class="eyebrow">Hier weitermachen</div><h2>${esc(next.title)}</h2><p class="muted">${esc(next.topic)} · ${next.minutes} Minuten</p></div><span class="topic-mark">▤</span></div><button class="btn primary" data-lesson="${next.id}">Lektion öffnen</button></article><article class="card"><div class="row between"><div><div class="eyebrow">Lernaktivität</div><h2>Diese Woche</h2></div><span class="tag">${p.streak||0} Tage aktiv</span></div>${weeklyChart()}</article></section><section class="card" style="margin-top:1rem"><div class="row between"><div><div class="eyebrow">Training & Medien</div><h2>Womit möchtest du starten?</h2><p><button class="btn secondary" data-lesson="optigrade-mcp">Dein Prüfungsgerät: OptiGrade MCP</button></p></div></div><div class="grid three"><button class="btn secondary" data-route="mediathek">🎬 Geräte-Mediathek</button><button class="btn secondary" data-go="practice">Fragen üben</button><button class="btn secondary" data-go="flashcards">Karteikarten</button><button class="btn secondary" data-route="calculator">MFA-Simulator</button><button class="btn secondary" data-route="cheatsheet">⚡ Spickzettel</button><button class="btn secondary" data-go="examSetup">Übungsprüfung</button><button class="btn ghost" data-route="topics">Lektionen</button></div></section><div class="notice small" style="margin-top:1rem">Lernhilfe · Übungsprüfungen sind keine offiziellen Prüfungen.</div>`;bindGo(el)}
function topicDescription(t){return {'Grundlagen':'Zweck, Ablauf und Begriffe der Klassifizierung.','Handelsklassen':'EU-Klassen und Muskelfleischanteile sicher einordnen.','Anatomie':'Körperregionen als Orientierung am Schlachtkörper.','ZP-Verfahren':'Messpunkte, Formel, Rechenübungen und Kontrolltoleranzen.','FOM-Gerät':'FOM, Ultraschall, AutoFOM, Prüfungen und Berechnungen.','Schnittführung':'Präsentation und Einfluss auf Messung und Gewicht.','Verwiegung':'Zeitpunkt, Protokoll und nachvollziehbare Dokumentation.'}[t]}
function topicsView(el){el.innerHTML=head('Lernpfad','Themen entdecken','Wähle ein Thema und lerne in kurzen, nachvollziehbaren Einheiten.')+`<div class="field"><label for="topic-search">Themen suchen</label><input class="search" id="topic-search" placeholder="z. B. Handelsklassen, Wiegen …"></div><div class="grid two" id="topic-list">${TOPICS.map((t,i)=>{const ls=lessons.filter(l=>l.topic===t);const done=ls.filter(l=>state.data.progress.lessons.includes(l.id)).length;return `<article class="card topic-card" data-topic-card="${esc(t.toLowerCase())}"><div class="topic-mark">${ICONS[i]}</div><div><h3>${esc(t)}</h3><p>${topicDescription(t)}</p><span class="tag gray">${done}/${ls.length} Lektion${ls.length!==1?'en':''}</span><button class="btn secondary smallbtn" data-topic="${esc(t)}">Lektionen ansehen</button></div></article>`}).join('')}</div><div class="notice small" style="margin-top:1rem">Praxisrelevante Anweisungen hängen vom zugelassenen Verfahren und deinem Betrieb ab. Quellen ansehen.</div>`;
el.querySelector('#topic-search').oninput=e=>el.querySelectorAll('[data-topic-card]').forEach(c=>c.classList.toggle('hide',!c.dataset.topicCard.includes(e.target.value.toLowerCase())));el.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>topicLessons(b.dataset.topic));}
function topicLessons(topic){const ls=lessons.filter(l=>l.topic===topic);const el=document.querySelector('#main');el.innerHTML=`<button class="btn ghost smallbtn" data-back>← Themen</button>${head('Thema',esc(topic),topicDescription(topic))}<div class="lesson-list">${ls.map(l=>`<article class="lesson-item"><div><b>${esc(l.title)}</b><small>${l.minutes} Min. · ${state.data.progress.lessons.includes(l.id)?'Abgeschlossen':'Lektion'}</small></div><button class="btn primary smallbtn" data-lesson="${l.id}">${state.data.progress.lessons.includes(l.id)?'Wiederholen':'Starten'}</button></article>`).join('')}</div>`;el.querySelector('[data-back]').onclick=()=>{state.route='topics';render()};bindLesson(el);}
function lessonFigure(f){return `<figure class="anatomy-hero-image"><a href="${esc(f.src)}" target="_blank" rel="noopener"><img src="${esc(f.src)}" alt="${esc(f.caption)}" loading="lazy"></a><figcaption>${esc(f.caption)} · Zum Vergrößern öffnen</figcaption></figure>`}
function lessonView(el){const l=state.lesson||lessons.find(x=>!state.data.progress.lessons.includes(x.id))||lessons[0];state.lesson=l;el.innerHTML=`<button class="btn ghost smallbtn" data-back>← Themen</button>${head(l.topic,esc(l.title),`${l.minutes} Minuten · Lerneinheit`)}<div class="notice small">Lernziel: ${esc(topicDescription(l.topic))} Lies die Erklärung${l.tables?.length?", prüfe die Referenztabelle":""} und übe anschließend die Themenfragen.</div><article class="card lesson-copy">${l.id==='anatomy'?pigDiagram():''}${l.body.map((p,i)=>`${/^\d+(?:\. | · )/.test(p)&&p.includes(':')?`<h3>${esc(p.slice(0,p.indexOf(':')))}</h3><p>${esc(p.slice(p.indexOf(':')+1).trim())}</p>`:`<p>${esc(p)}</p>`}${i===0&&l.id==='classes'?`<div class="grid two">${[['S','≥ 60 %'],['E','55–&lt;60 %'],['U','50–&lt;55 %'],['R','45–&lt;50 %'],['O','40–&lt;45 %'],['P','&lt; 40 %']].map(([c,v])=>`<div class="card tight"><b>${c}</b><span class="muted"> · ${v}</span></div>`).join('')}</div>`:''}${(l.figures||[]).filter(f=>f.afterParagraph===i).map(lessonFigure).join('')}`).join('')}${l.id==='anatomy'?anatomyReference():''}${(l.figures||[]).filter(f=>!Number.isInteger(f.afterParagraph)).map(lessonFigure).join('')}${lessonReferences(l)}${l.source?`<p class="small muted">${esc(l.source)}</p>`:``}<div class="row between" style="margin-top:1.1rem"><label class="switch"><input type="checkbox" id="english-explain" ${state.lessonEnglish?'checked':''}> English explanation</label><button class="btn primary" id="complete-lesson">Lektion abschließen</button></div><div id="english-copy" class="notice hide" style="margin-top:.8rem">${esc(l.en)}</div></article><section class="card" style="margin-top:1rem"><h2>Wissen prüfen</h2><p class="muted">${l.questionIds?.length ? "Übe die Fragen zu dieser Lektion." : `Übe direkt Fragen aus „${esc(l.topic)}“.`}</p><button class="btn secondary" id="lesson-quiz">${l.questionIds?.length ? "Lektionsfragen starten" : "Themenfragen starten"}</button></section>`;
el.querySelector('[data-back]').onclick=()=>{state.route='topics';render()};el.querySelector('#english-explain').onchange=e=>{state.lessonEnglish=e.target.checked;el.querySelector('#english-copy').classList.toggle('hide',!e.target.checked)};el.querySelector('#english-copy').classList.toggle('hide',!state.lessonEnglish);el.querySelector('#complete-lesson').onclick=async()=>{await api('/event','POST',{type:'lesson',lessonId:l.id});await refresh();toast('Lektion abgeschlossen');state.route='topics';render()};el.querySelector('#lesson-quiz').onclick=()=>{state.filter=l.topic;startPractice(l.topic,5,'text',l.questionIds)};}
function pigDiagram(){return `<figure class="anatomy-hero-image"><img src="/anatomy-directions-clean.png" alt="Das bereinigte Anatomieposter mit einem Schweineskelett und den Richtungsbegriffen Cranial, Caudal, Dorsal, Ventral, Medial, Lateral, Proximal und Distal"><figcaption>Richtungsbegriffe am Schwein · Lernposter</figcaption></figure>`}
function selectCut(key,el){const cut=CUTS_DATA[key];if(!cut)return;const card=el.querySelector('#active-cut-card');if(card){card.innerHTML=`<div class="row between"><div><div class="eyebrow">${esc(cut.latin)}</div><h3 style="margin:0">${esc(cut.name)}</h3></div><button class="btn secondary smallbtn" data-speak="${esc(cut.name + ' · ' + cut.latin)}">🔊 Aussprache anhören</button></div><p style="margin-top:.7rem"><b>Mess- & Klassifizierungsrelevanz:</b> ${esc(cut.role)}</p><p class="small muted">${esc(cut.details)}</p><div class="notice small" style="margin-top:.6rem"><b>Vorgaben (SchwHKlV & 1. FlGDV):</b> ${esc(cut.rules)}</div>`;}el.querySelectorAll('[data-cut]').forEach(p=>p.classList.toggle('active',p.dataset.cut===key));el.querySelectorAll('[data-cut-key]').forEach(b=>b.classList.toggle('active',b.dataset.cutKey===key));bindGo(el);}
function anatomyReference(){return `<section class="anatomy-terms" aria-labelledby="anatomy-terms-title"><h3 id="anatomy-terms-title">Richtungsbegriffe am Schlachtkörper</h3><dl class="anatomy-term-grid">${[['Cranial / kranial','kopfwärts'],['Caudal','schwanzwärts'],['Dorsal','rückenseitig, zur Wirbelsäule'],['Ventral','bauchseitig'],['Proximal','rumpfwärts (am Gliedmaß)'],['Distal','vom Rumpf weg (am Gliedmaß)'],['Medial','zur Körpermittellinie hin'],['Lateral','von der Körpermittellinie weg']].map(([term,meaning])=>`<div><dt>${term} <button class="speak-btn" data-speak="${term.split('/')[0].trim()}" title="Aussprache anhören">🔊</button></dt><dd>${meaning}</dd></div>`).join('')}</dl><h3>Interaktiver Teilstücke-Explorer & Trennschnitte</h3><p>Tippe auf ein Teilstück in der Grafik oder in der Leiste, um Lage, Messstellen und gesetzliche Vorgaben nach SchwHKlV &amp; 1. FlGDV zu sehen:</p><div class="cut-explorer"><div class="cut-explorer-canvas"><svg class="carcass-map-svg" viewBox="0 0 680 185" aria-label="Schlachtkörper-Teilstücke interaktiv"><path d="M 40,90 Q 60,35 150,30 Q 320,25 500,28 Q 590,30 630,70 Q 650,110 600,140 Q 480,155 350,150 Q 200,155 110,135 Q 50,120 40,90 Z" fill="#fcf6f0" stroke="#d5c1b5" stroke-width="2"/><path class="carcass-cut-path" data-cut="kopf" d="M 40,90 Q 55,45 110,40 L 115,130 Q 60,120 40,90 Z"/><text x="75" y="90" font-size="11" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Kopf</text><path class="carcass-cut-path" data-cut="kamm" d="M 110,40 Q 180,32 230,30 L 235,135 Q 170,145 115,130 Z"/><text x="170" y="85" font-size="11" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Kamm / Bug</text><path class="carcass-cut-path" data-cut="kotelett" d="M 230,30 Q 360,26 470,28 L 470,85 Q 360,82 232,85 Z"/><text x="350" y="58" font-size="12" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Kotelett (M. longissimus dorsi)</text><path class="carcass-cut-path" data-cut="bauch" d="M 232,85 Q 360,82 470,85 L 470,145 Q 350,152 235,135 Z"/><text x="350" y="120" font-size="11" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Bauch & Wamme</text><path class="carcass-cut-path" data-cut="schinken" d="M 470,28 Q 570,30 620,65 Q 640,100 600,135 L 530,148 L 470,145 Z"/><text x="545" y="90" font-size="12" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Schinken (Keule)</text><path class="carcass-cut-path" data-cut="eisbein" d="M 160,138 L 195,138 L 190,172 L 165,172 Z M 520,148 L 560,142 L 555,172 L 525,172 Z"/><text x="178" y="158" font-size="9" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Haxe</text><text x="542" y="160" font-size="9" font-weight="700" fill="#6d4c3d" text-anchor="middle" pointer-events="none">Eisbein</text></svg></div><div class="preset-pills" style="margin-top:.85rem">${Object.entries(CUTS_DATA).map(([k,v])=>`<button class="btn secondary smallbtn" data-cut-key="${k}">${esc(v.name)}</button>`).join('')}</div><div id="active-cut-card" class="cut-info-card"><b>Tippe auf ein Teilstück in der Grafik oder den Tasten oben</b>, um die anatomische Bezeichnung, Messrelevanz und Schnittführungsregeln zu sehen.</div></div><div class="anatomy-image-grid"><figure><img src="/anatomy-cuts-clean.png" alt="Übersicht zur Zerlegung des Schweins mit Teilstücken, Trennschnitten und deren Trennungen" loading="lazy"><figcaption>Teilstücke und beispielhafte Trennschnitte · bereinigte Ansicht. <a href="/anatomy-cuts.jpg" target="_blank" rel="noopener">Originalfoto zum Abgleich</a> · <a href="/anatomy-cuts-clean.png" target="_blank" rel="noopener">Großansicht öffnen</a></figcaption></figure></div></section>`}
function bindGo(el){el.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.route=b.dataset.go;render()});el.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render()});el.querySelectorAll('[data-speak]').forEach(b=>b.onclick=e=>{e.stopPropagation();speak(b.dataset.speak)});el.querySelectorAll('[data-cut]').forEach(p=>p.onclick=()=>selectCut(p.dataset.cut,el));el.querySelectorAll('[data-cut-key]').forEach(b=>b.onclick=()=>selectCut(b.dataset.cutKey,el));bindLesson(el)}function bindLesson(el){el.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson=lessons.find(l=>l.id===b.dataset.lesson);state.lessonEnglish=false;state.route='lesson';render()})}
function practiceView(el){el.innerHTML=head('Training','Übung zusammenstellen','Stelle dein Training passend zu deinem Lernziel ein.')+`<section class="card"><div class="field"><label for="practice-topic">Thema</label><select id="practice-topic"><option>Alle Themen</option>${TOPICS.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Anzahl der Fragen</label><div class="checks">${[5,10,15,20].map(n=>`<label class="check-label"><input type="radio" name="count" value="${n}" ${n===10?'checked':''}> ${n}</label>`).join('')}</div></div><div class="field"><label>Fragetypen</label><div class="checks"><label class="check-label"><input type="checkbox" id="include-text" checked> Textfragen</label><label class="check-label"><input type="checkbox" id="include-image" checked> Abbildungen</label></div><small>Abbildungen dienen der Orientierung und sind keine verbindlichen Messanweisungen.</small></div><button class="btn primary" id="start-practice">Training starten</button></section><div class="grid two" style="margin-top:1rem"><button class="btn secondary" data-route="flashcards">Karteikarten wiederholen</button><button class="btn secondary" data-route="mistakes">Fehler wiederholen (${state.data.progress.mistakes?.length||0})</button><button class="btn secondary" data-route="examSetup">Übungsprüfung starten</button><button class="btn ghost" data-route="topics">Lektionen ansehen</button></div>`;el.querySelector('#start-practice').onclick=()=>{const topic=el.querySelector('#practice-topic').value;const count=Number(el.querySelector('[name=count]:checked').value);const types=[...(el.querySelector('#include-text').checked?['text']:[]),...(el.querySelector('#include-image').checked?['image']:[])];if(!types.length){toast('Wähle mindestens einen Fragetyp.');return}startPractice(topic,count,types)};el.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render()})}
function startPractice(topic,count,types,questionIds){types=Array.isArray(types)?types:[types];let qs=questions.filter(q=>(questionIds ? questionIds.includes(q.id) : (topic==='Alle Themen'||q.topic===topic))&&types.includes(questionType(q)));if(!qs.length){toast('Für diese Auswahl gibt es keine Fragen.');return}const available=qs.length;qs=balancedQuestions(qs,count);if(qs.length<count)toast(`Für diese Auswahl sind ${available} Fragen verfügbar.`);state.practice={questions:qs,index:0,results:[],topic,types,review:false};state.route='quiz';state.selected=null;state.feedback=false;render()}
function quizView(el){const pr=state.practice;if(!pr){state.route='practice';return practiceView(el)}const q=pr.questions[pr.index];el.innerHTML=`<div class="question-meta"><button class="btn ghost smallbtn" id="quit-quiz">✕ Beenden</button><span>Frage ${pr.index+1} von ${pr.questions.length}</span><button class="btn ghost smallbtn" id="bookmark" aria-label="Frage merken">${state.data.progress.bookmarks?.includes(q.id)?'★':'☆'} Merken</button></div><div class="progress-track" style="margin:.8rem 0 1rem"><div class="progress-fill" style="width:${pct(pr.index,pr.questions.length)}%"></div></div><div class="eyebrow">${esc(q.topic)}</div><h1>${esc(q.q)}</h1><p class="muted">Eine Antwort ist richtig.</p>${questionType(q)==='image'?pigDiagram():''}<div class="answer-list">${q.opts.map((o,i)=>`<button class="answer-option ${state.selected===i?'selected':''} ${state.feedback&&i===q.answer?'correct':''} ${state.feedback&&state.selected===i&&i!==q.answer?'incorrect':''}" data-answer="${i}" ${state.feedback?'disabled':''}><span>${String.fromCharCode(65+i)} · </span>${esc(o)}</button>`).join('')}</div>${state.feedback?`<div class="notice ${state.selected===q.answer?'success':'error'}"><b>${state.selected===q.answer?'Richtig!':'Noch nicht ganz.'}</b> ${esc(q.why)}</div>`:''}<div class="row between" style="margin-top:1rem"><span class="small muted">Übung · keine offizielle Prüfung</span><button class="btn primary" id="quiz-next" ${state.selected===null&&!state.feedback?'disabled':''}>${state.feedback?(pr.index===pr.questions.length-1?'Ergebnis ansehen':'Nächste Frage'):'Antwort prüfen'}</button></div>`;
 el.querySelector('#quit-quiz').onclick=()=>{state.route='practice';render()};el.querySelector('#bookmark').onclick=async()=>{await api('/event','POST',{type:'bookmark',questionId:q.id});await refresh();quizView(document.querySelector('#main'))};el.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(!state.feedback){state.selected=Number(b.dataset.answer);quizView(el)}});el.querySelector('#quiz-next').onclick=async()=>{if(!state.feedback){if(state.selected===null)return;state.feedback=true;const correct=state.selected===q.answer;playSound(correct);pr.results.push({q,correct});await api('/event','POST',{type:'answer',correct,topic:q.topic,questionId:q.id});await refresh();quizView(document.querySelector('#main'));return}if(pr.index<pr.questions.length-1){pr.index++;state.selected=null;state.feedback=false;render()}else{state.practice.results=pr.results;state.route='practiceResult';render()}};
}
function practiceResultView(el){const results=state.practice?.results||[];if(!results.length){state.route='practice';return practiceView(el)}const good=results.filter(r=>r.correct).length;const by=results.reduce((a,r)=>((a[r.q.topic]||=[]).push(r),a),{});el.innerHTML=head('Trainingsergebnis','Gut geübt','Fragen und Erklärungen kannst du jederzeit erneut aufrufen.')+`<section class="card hero"><div class="metric" style="color:white">${pct(good,results.length)} %</div><h2>${good} von ${results.length} richtig</h2><p class="muted">Antwortgenauigkeit dieser Runde</p></section><section class="card" style="margin-top:1rem"><h2>Nach Themen</h2>${Object.entries(by).map(([t,arr])=>`<div class="topic-line" style="margin:.8rem 0"><b>${esc(t)}</b><div class="progress-track"><div class="progress-fill" style="width:${pct(arr.filter(r=>r.correct).length,arr.length)}%"></div></div><span>${arr.filter(r=>r.correct).length}/${arr.length}</span></div>`).join('')}</section><section class="stack" style="margin-top:1rem"><h2>Erklärungen</h2>${results.map((r,i)=>`<article class="card tight"><div class="row between"><b>${i+1}. ${esc(r.q.topic)}</b><span class="tag ${r.correct?'':'gold'}">${r.correct?'Richtig':'Wiederholen'}</span></div><p>${esc(r.q.q)}</p><p class="small">${esc(r.q.why)}</p></article>`).join('')}<div class="row"><button class="btn primary" id="practice-again">Weiter üben</button><button class="btn secondary" data-go="mistakes">Fehler wiederholen</button><button class="btn ghost" data-go="progress">Fortschritt</button></div></section>`;el.querySelector('#practice-again').onclick=()=>{state.route='practice';render()};el.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.route=b.dataset.go;render()})}
function flashView(el){const deck=state.flashAll?cards:dueCards(cards,state.data.progress.cards,today());if(!deck.length){el.innerHTML=head('Wiederholen','Heute alles wiederholt','Die nächsten Karten erscheinen an ihrem Wiederholungstermin.')+'<section class="card"><button class="btn secondary" id="flash-all">Alle Karten trotzdem ansehen</button></section>';el.querySelector('#flash-all').onclick=()=>{state.flashAll=true;state.flashIndex=0;render()};return}const index=state.flashIndex%deck.length;const [id,front,back]=deck[index];const rec=state.data.progress.cards?.[id];el.innerHTML=head('Wiederholen','Karteikarten',`${index+1} von ${deck.length} · ${state.flashAll?"Alle Karten":"Heute fällig oder neu"} · ${rec?.repetitions?`${rec.repetitions} Wiederholungen`:'Heute neu'}`)+`<button class="btn ghost smallbtn" id="flash-mode">${state.flashAll?"Nur fällige Karten":"Alle Karten ansehen"}</button><article class="card flashcard" id="flashcard" role="button" tabindex="0" aria-label="Karte umdrehen">${state.flashRevealed?`<div class="eyebrow">Antwort</div><div class="flash-answer">${esc(back)}</div>`:`<div class="eyebrow">Frage</div><h2>${esc(front)}</h2><span class="muted">Tippen zum Umdrehen</span>`}</article><div class="row between" style="margin-top:1rem"><button class="btn ghost" id="flash-prev">← Zurück</button>${state.flashRevealed?`<div class="row"><button class="btn secondary" data-confidence="hard">Schwer</button><button class="btn secondary" data-confidence="ok">Gewusst</button><button class="btn primary" data-confidence="easy">Einfach</button></div>`:`<button class="btn primary" id="flash-reveal">Antwort zeigen</button>`}<button class="btn ghost" id="flash-next">Weiter →</button></div><div class="notice small" style="margin-top:1rem">Wiederholungsabstand passt sich deiner Einschätzung an: schwer heute, gewusst morgen, einfach in drei Tagen.</div>`;el.querySelector('#flash-mode').onclick=()=>{state.flashAll=!state.flashAll;state.flashIndex=0;state.flashRevealed=false;render()};const flip=()=>{state.flashRevealed=!state.flashRevealed;render()};el.querySelector('#flashcard').onclick=flip;el.querySelector('#flashcard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}};el.querySelector('#flash-reveal')?.addEventListener('click',flip);el.querySelector('#flash-prev').onclick=()=>{state.flashIndex=(index+deck.length-1)%deck.length;state.flashRevealed=false;render()};el.querySelector('#flash-next').onclick=()=>{state.flashIndex=(index+1)%deck.length;state.flashRevealed=false;render()};el.querySelectorAll('[data-confidence]').forEach(b=>b.onclick=async()=>{await api('/event','POST',{type:'card',cardId:id,confidence:b.dataset.confidence});await refresh();state.flashIndex=state.flashAll?(index+1)%deck.length:index;state.flashRevealed=false;render()})}
function examSetupView(el){el.innerHTML=head('Prüfungstraining','Übungsprüfung','Trainiere eine Prüfungssituation. Auswertung und Erklärungen erscheinen erst am Ende.')+`<div class="notice warning"><b>Keine offizielle Prüfung.</b> Diese selbst zusammengestellte Übung deckt ausgewählte Grundlagen ab und ersetzt keine Prüfungsvorbereitung nach Ausbildungsplan.</div><section class="card" style="margin-top:1rem"><div class="field"><label for="exam-count">Fragen</label><select id="exam-count"><option value="10">10 Fragen · ca. 10 Minuten</option><option value="15">15 Fragen · ca. 15 Minuten</option><option value="30">30 Fragen · ca. 30 Minuten</option><option value="50">50 Fragen · ca. 50 Minuten</option></select></div><div class="field"><label for="exam-topic">Thema</label><select id="exam-topic"><option>Alle Themen</option>${TOPICS.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><label class="switch"><input type="checkbox" id="exam-timer"> Timer einschalten</label><button class="btn primary" id="exam-start" style="margin-top:1rem">Übungsprüfung starten</button></section>`;el.querySelector('#exam-start').onclick=()=>startExam(Number(el.querySelector('#exam-count').value),el.querySelector('#exam-topic').value,el.querySelector('#exam-timer').checked)}
function startExam(count,topic,timer){let qs=questions.filter(q=>topic==='Alle Themen'||q.topic===topic);const available=qs.length;qs=balancedQuestions(qs,count);if(qs.length<count)toast(`Für dieses Thema sind ${available} Fragen verfügbar.`);state.exam={questions:qs,index:0,answers:[],topic,timer,started:Date.now(),seconds:qs.length*60};state.route='exam';render();if(timer)examTicker()}
function examTicker(){clearInterval(state.exam?.ticker);if(!state.exam?.timer)return;state.exam.ticker=setInterval(()=>{if(!state.exam)return;state.exam.seconds--;if(state.exam.seconds<=0){clearInterval(state.exam.ticker);finishExam()}else{const t=document.querySelector('#exam-time');if(t)t.textContent=`${Math.floor(state.exam.seconds/60)}:${String(state.exam.seconds%60).padStart(2,'0')}`}},1000)}
function examView(el){const x=state.exam;if(!x)return examSetupView(el);const q=x.questions[x.index];el.innerHTML=`<div class="question-meta"><button class="btn ghost smallbtn" id="exam-exit">Prüfung verlassen</button><span>Frage ${x.index+1} von ${x.questions.length}</span>${x.timer?`<span class="tag" id="exam-time">${Math.floor(x.seconds/60)}:${String(x.seconds%60).padStart(2,'0')}</span>`:''}</div><div class="progress-track" style="margin:.8rem 0 1rem"><div class="progress-fill" style="width:${pct(x.index,x.questions.length)}%"></div></div><div class="eyebrow">${esc(q.topic)}</div><h1>${esc(q.q)}</h1>${questionType(q)==='image'?pigDiagram():''}<div class="answer-list">${q.opts.map((o,i)=>`<button class="answer-option ${x.answers[x.index]===i?'selected':''}" data-exam-answer="${i}"><span>${String.fromCharCode(65+i)} · </span>${esc(o)}</button>`).join('')}</div><div class="row between"><button class="btn ghost" id="exam-prev" ${x.index===0?'disabled':''}>← Zurück</button><span class="small muted">Feedback am Prüfungsende</span><button class="btn primary" id="exam-next">${x.index===x.questions.length-1?'Abgeben':'Weiter →'}</button></div>`;el.querySelector('#exam-exit').onclick=()=>{if(confirm('Übungsprüfung wirklich verlassen? Antworten werden nicht gewertet.')){clearInterval(x.ticker);state.exam=null;state.route='examSetup';render()}};el.querySelectorAll('[data-exam-answer]').forEach(b=>b.onclick=()=>{x.answers[x.index]=Number(b.dataset.examAnswer);examView(el)});el.querySelector('#exam-prev').onclick=()=>{x.index--;render()};el.querySelector('#exam-next').onclick=()=>{x.answers[x.index]??=null;if(x.index<x.questions.length-1){x.index++;render()}else finishExam()}}
async function finishExam(){const x=state.exam;if(!x)return;clearInterval(x.ticker);const results=x.questions.map((q,i)=>({q,correct:x.answers[i]===q.answer,selected:x.answers[i]}));for(const r of results)if(r.selected!==null&&r.selected!==undefined)await api('/event','POST',{type:'answer',correct:r.correct,topic:r.q.topic,questionId:r.q.id});await api('/event','POST',{type:'exam',correct:results.filter(r=>r.correct).length,total:results.length,topic:x.topic});await refresh();state.examResult={results,topic:x.topic,elapsed:Math.round((Date.now()-x.started)/60000)};state.exam=null;state.route='examResult';render()}
function examResultView(el){const x=state.examResult;if(!x)return progressView(el);const good=x.results.filter(r=>r.correct).length;const by=Object.groupBy?Object.groupBy(x.results,r=>r.q.topic):x.results.reduce((a,r)=>((a[r.q.topic]||=[]).push(r),a),{});el.innerHTML=`<div class="print-header"><h2>Klassenklar · Übungsprüfungs-Nachweis</h2><p>Lernende/r: <b>${esc(state.data.name)}</b> · Gruppe: <b>${esc(state.data.group)}</b> · Datum: ${new Date().toLocaleDateString('de-DE')} · Bearbeitungszeit: ${x.elapsed} Min.</p><p>Ergebnis: <b>${good} von ${x.results.length} richtig (${pct(good,x.results.length)} %)</b></p></div>`+head('Ergebnis','Übungsprüfung beendet',`Bearbeitungszeit: ${x.elapsed} Min. · ${esc(x.topic)}`)+`<section class="card hero"><div class="metric" style="color:white">${pct(good,x.results.length)} %</div><h2>${good} von ${x.results.length} richtig</h2><p class="muted">Das ist eine Lernrückmeldung, keine amtliche Bewertung.</p><div class="progress-track"><div class="progress-fill" style="width:${pct(good,x.results.length)}%"></div></div></section><section class="card" style="margin-top:1rem"><h2>Nach Themen</h2>${Object.entries(by).map(([t,arr])=>`<div class="topic-line" style="margin:.8rem 0"><b>${esc(t)}</b><div class="progress-track"><div class="progress-fill" style="width:${pct(arr.filter(r=>r.correct).length,arr.length)}%"></div></div><span>${arr.filter(r=>r.correct).length}/${arr.length}</span></div>`).join('')}</section><section class="stack" style="margin-top:1rem"><h2>Antworten & Erklärungen</h2>${x.results.map((r,i)=>`<article class="card tight"><div class="row between"><b>${i+1}. ${esc(r.q.topic)}</b><span class="tag ${r.correct?'':'gold'}">${r.correct?'Richtig':'Wiederholen'}</span></div><p>${esc(r.q.q)}</p><p class="small"><b>Deine Antwort:</b> ${r.selected===null||r.selected===undefined?'Keine Antwort':esc(r.q.opts[r.selected])}</p><p class="small"><b>Erklärung:</b> ${esc(r.q.why)}</p></article>`).join('')}<div class="row"><button class="btn primary" id="exam-again">Noch einmal üben</button><button class="btn secondary" id="print-exam">🖨 Nachweis drucken / PDF</button><button class="btn secondary" data-go="progress">Fortschritt ansehen</button></div></section>`;el.querySelector('#exam-again').onclick=()=>{state.route='examSetup';render()};el.querySelector('#print-exam')?.addEventListener('click',()=>window.print());el.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.route=b.dataset.go;render()})}
async function refresh(){state.data=await api('/state')}
function mistakesView(el){const ids=state.data.progress.mistakes||[];const list=ids.map(m=>questions.find(q=>q.id===m.id)).filter(Boolean);el.innerHTML=head('Wiederholen','Fehlertraining',list.length?`${list.length} Frage${list.length!==1?'n':''} zum erneuten Üben.`:'Keine offenen Fehler – starte ein Training, um neue zu sammeln.')+(list.length?`<div class="stack">${list.map(q=>`<article class="card"><div class="eyebrow">${esc(q.topic)}</div><h3>${esc(q.q)}</h3><p class="muted">${esc(q.why)}</p><button class="btn secondary smallbtn" data-remove="${q.id}">Als wiederholt markieren</button></article>`).join('')}<button class="btn primary" id="retry-all">Fehlerfragen erneut üben</button></div>`:`<button class="btn primary" data-go="practice">Training starten</button>`);el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{await api('/event','POST',{type:'mistakeCleared',questionId:b.dataset.remove});await refresh();mistakesView(el)});el.querySelector('#retry-all')?.addEventListener('click',()=>{state.practice={questions:list,index:0,results:[],topic:'Fehlertraining',types:['text'],review:true};state.route='quiz';render()});el.querySelector('[data-go]')?.addEventListener('click',()=>{state.route='practice';render()})}
function progressView(el){const p=state.data.progress;const daily=totalToday();const topicRows=TOPICS.map(t=>{const d=p.topic?.[t]||{answered:0,correct:0};const accuracy=pct(d.correct,d.answered);const level=d.answered>=5&&accuracy>=80?'Sicher':d.answered?accuracy>=60?'Im Aufbau':'Übungsbedarf':'Noch offen';return `<div class="topic-line" style="margin:.85rem 0"><span>${esc(t)}</span><div class="progress-track"><div class="progress-fill" style="width:${accuracy}%"></div></div><span title="${d.correct}/${d.answered} richtig">${d.answered?accuracy+'%':'—'}</span></div><div class="small muted" style="margin:-.55rem 0 .45rem 150px">${level} · ${d.answered} Fragen</div>`}).join('');el.innerHTML=head('Dein Lernstand','Fortschritt','Lektionen, Antwortgenauigkeit, Wiederholungen und Praxis werden getrennt erfasst.')+`<div class="grid three"><article class="card"><div class="metric">${p.lessons.length}/${lessons.length}</div><div class="metric-label">Abgeschlossene Lektionen</div></article><article class="card"><div class="metric">${pct(p.correct,p.answered)}%</div><div class="metric-label">Antwortgenauigkeit · ${p.answered} Antworten</div></article><article class="card"><div class="metric">${p.answered}</div><div class="metric-label">Beantwortete Fragen</div></article></div><div class="grid two" style="margin-top:1rem"><article class="card"><div class="row between"><h2>Antworten diese Woche</h2><span class="tag">Heute ${daily}</span></div>${weeklyChart()}</article><article class="card"><h2>Praxis-Checkliste</h2><p class="small muted">Nur durch eine Ausbilderin oder einen Ausbilder bestätigt. Online-Übungen zählen nicht als Praxisnachweis.</p>${["Arbeitsplatz vorbereiten","Messpunkte sicher finden","Waage korrekt bedienen","Ergebnis dokumentieren","Referenzpräsentation und Schnittführung prüfen","Morgenkontrolle am Betriebsgerät durchführen","Softwareversionen und Prüfergebnisse abgleichen","Messfehler erkennen und korrekt reagieren"].map(item=>`<div class="row between" style="padding:.5rem 0;border-bottom:1px solid var(--line)"><span>${esc(item)}</span><span class="tag ${(p.practical||[]).includes(item)?'':'gray'}">${(p.practical||[]).includes(item)?'Bestätigt':'Offen'}</span></div>`).join('')}</article></div><section class="card" style="margin-top:1rem"><h2>Antwortgenauigkeit nach Thema</h2>${topicRows}</section>${studyChecklist()}`;bindGo(el)}
function settingsView(el){const s=state.data.settings;el.innerHTML=head('Persönlich','Einstellungen','Passe Lernziel, Farbschema und Darstellung an.')+`<section class="card"><form id="settings-form"><div class="field"><label for="goal">Tagesziel in Fragen</label><input id="goal" name="goal" type="number" min="1" max="100" value="${s.goal}"></div><div class="field"><label for="exam-date">Prüfungstermin (optional)</label><input id="exam-date" name="examDate" type="date" value="${esc(s.examDate||'')}"></div><div class="field"><label for="theme-select">Farbschema</label><select id="theme-select"><option value="auto" ${localStorage.getItem('kk_theme')!=='light'&&localStorage.getItem('kk_theme')!=='dark'?'selected':''}>Automatisch (System)</option><option value="light" ${localStorage.getItem('kk_theme')==='light'?'selected':''}>Hell</option><option value="dark" ${localStorage.getItem('kk_theme')==='dark'?'selected':''}>Dunkel</option></select></div><div class="field"><label for="font-scale">Schriftgröße</label><select id="font-scale" name="fontScale"><option value="0.9" ${s.fontScale===.9?'selected':''}>Kompakt</option><option value="1" ${s.fontScale===1?'selected':''}>Standard</option><option value="1.15" ${s.fontScale===1.15?'selected':''}>Groß</option><option value="1.3" ${s.fontScale===1.3?'selected':''}>Sehr groß</option></select></div><div class="field"><label for="language">Oberfläche</label><select id="language" name="language"><option value="de">Deutsch</option><option value="en" ${s.language==='en'?'selected':''}>English lesson explanations · Menüs bleiben Deutsch</option></select></div><label class="switch" style="margin:.85rem 0"><input type="checkbox" id="sound-toggle" ${s.sound!==false?'checked':''}> Audio-Effekte bei Übungsfragen</label><div class="field"><label>FOM-Modell</label><select disabled><option>Betriebsmodell noch nicht hinterlegt</option></select><small>FOM- und AutoFOM-Lektionen sind verfügbar. Für die Praxis die Unterlagen des konkreten Betriebsmodells verwenden.</small></div><button class="btn primary">Einstellungen speichern</button></form></section><section class="card" style="margin-top:1rem"><h2>Lernstand sichern</h2><p class="muted">Exportiere deine Daten als JSON oder importiere eine zuvor gespeicherte Datei.</p><div class="row"><button class="btn secondary" id="export-data">Lernstand exportieren</button><label class="btn ghost" for="import-file">Datei importieren</label><input id="import-file" class="hide" type="file" accept="application/json,.json"></div></section><section class="card" style="margin-top:1rem"><h2>Lokale Konten</h2><p class="small muted">Dein Konto und Fortschritt liegen in der lokalen Serverdatei. Für gemeinsam genutzte Geräte abmelden. Ohne HTTPS nicht öffentlich bereitstellen.</p></section>`;el.querySelector('#theme-select').onchange=e=>{if(e.target.value==='auto'){localStorage.removeItem('kk_theme');applyTheme(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');}else{applyTheme(e.target.value);}};el.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.sound=el.querySelector('#sound-toggle').checked;await api('/settings','POST',b);await refresh();setFont();toast('Einstellungen gespeichert')};el.querySelector('#export-data').onclick=async()=>{const d=await api('/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='klassenklar-lernstand.json';a.click();URL.revokeObjectURL(a.href)};el.querySelector('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await api('/import','POST',JSON.parse(await f.text()));await refresh();toast('Lernstand importiert');settingsView(el)}catch(err){toast(err.message)}}}
function sourcesView(el){el.innerHTML=head('Nachschlagen','Quellen & Lernhinweise','Kernaussagen wurden mit amtlichen Rechtsquellen abgeglichen. Rechtsstand und betriebliche Anweisungen beachten.')+`<section class="card"><h2>Amtliche Grundlagen</h2><ul class="source-list">${sources.map(([n,u])=>`<li><a href="${u}" target="_blank" rel="noopener">${esc(n)} ↗</a></li>`).join('')}</ul></section><section class="card" style="margin-top:1rem"><h2>Abgrenzung</h2><p>Die App erklärt ausgewählte Grundlagen und liefert Übungsfragen. Sie bildet keine amtliche Prüfung vollständig ab. Praxisaufgaben gelten erst nach Bestätigung durch eine ausbildende Person als erledigt.</p><p>Die Geräte-Lektionen beruhen auf den fotografierten Schulungsunterlagen: Geräteprüfanleitung Stand 14.03.2016, Zulassungsübersichten Stand 07.12.2020 und ergänzende Handouts. Menüs, Faktoren, Softwareversionen und Prüfsummen werden mit den Unterlagen der konkreten Anlage verglichen. Zusätzlich wurden die bereitgestellte gescannte Geräteprüfanleitung und die zwei inhaltsgleichen Textfassungen der Schulungsbroschüre ausgewertet. Originalseiten zur OptiGrade-Prüfung sind in der Geräte-Lektion vergrößerbar. Datierte Gerätewerte sind nicht als aktueller Zulassungsstand der konkreten Anlage bestätigt.</p><p class="small muted">Recherche geprüft am 4. Oktober 2026 anhand der verlinkten amtlichen Quellen. Bei Rechtsänderungen gilt stets der aktuelle amtliche Text.</p></section>`}
function moreView(el){el.innerHTML=head('Mehr','Deine Lernwerkzeuge')+`<div class="grid two"><button class="btn secondary" data-route="mediathek">🎬 Geräte-Mediathek & Videos</button><button class="btn secondary" data-route="cheatsheet">⚡ Spickzettel & Formeln</button><button class="btn secondary" data-route="calculator">MFA-Rechenwerkstatt & Simulator</button><button class="btn secondary" data-route="mistakes">Fehler wiederholen · ${state.data.progress.mistakes?.length||0}</button><button class="btn secondary" data-route="flashcards">Karteikarten</button><button class="btn secondary" data-route="examSetup">Übungsprüfung</button><button class="btn secondary" data-route="settings">Einstellungen</button><button class="btn secondary" data-route="sources">Quellen & Lernhinweise</button><button class="btn ghost" data-route="progress">Fortschritt</button></div><div class="notice small" style="margin-top:1rem">Die Übungsprüfung ist keine offizielle Prüfung. Fortschritt unterscheidet Lektionen, Antwortgenauigkeit, Themenstand und trainerbestätigte Praxis.</div>`;el.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render()})}
function cheatsheetView(el){el.innerHTML=head('Nachschlagen','⚡ Spickzettel & Schnellübersicht','Formeln, Handelsklassen, Fristen, Schnittführung und Prüfwerte kompakt auf einen Blick.')+`<div class="field"><label for="sheet-search">Spickzettel filtern</label><input class="search" id="sheet-search" placeholder="z. B. 45 Minuten, Formel, Korrekturfaktor, OptiGrade, Dreieck, Eichfrist, Tara ..." value="${esc(state.cheatsheetSearch||'')}"></div><div class="grid two" id="sheet-cards"><article class="cheatsheet-card" data-sheet-item="handelsklassen s e u r o p m v grenzen gewicht schlachtkörper 60 55 50 45 40 eber sau"><h3>◈ EU-Handelsklassen & Kategorien</h3><p class="small muted">Einstufung nach geschätztem Muskelfleischanteil</p><table class="table-compact"><thead><tr><th>Klasse</th><th>Muskelfleischanteil</th><th>Bedeutung</th></tr></thead><tbody><tr><td><b>S</b></td><td>≥ 60 %</td><td>Spitzenklasse</td></tr><tr><td><b>E</b></td><td>55 % bis &lt; 60 %</td><td>Standard-Handelsklasse</td></tr><tr><td><b>U</b></td><td>50 % bis &lt; 55 %</td><td>Guter Fleischanteil</td></tr><tr><td><b>R</b></td><td>45 % bis &lt; 50 %</td><td>Mittlerer Fleischanteil</td></tr><tr><td><b>O</b></td><td>40 % bis &lt; 45 %</td><td>Geringer Fleischanteil</td></tr><tr><td><b>P</b></td><td>&lt; 40 %</td><td>Sehr geringer Fleischanteil</td></tr><tr><td><b>M</b></td><td>—</td><td>Sauen (muss einmal geferkelt haben)</td></tr><tr><td><b>V</b></td><td>—</td><td>Eber & Altschneider zur Zucht</td></tr></tbody></table><p class="small" style="margin-top:.6rem"><b>Gewichtsbereich S–P:</b> 50,0 kg bis 119,9 kg Schlachtgewicht.<br><b>Ebermerkmale:</b> Roter Schwellkörper am Schloßknochen, Samenstrang, Spiegelschnitt, Muskel im Bauchspeck.</p></article><article class="cheatsheet-card" data-sheet-item="formel zp zweipunkt sonde optigrade fom berechnung f star g mass anlage 2 3"><h3>⊙ Gesetzliche Berechnungsformeln</h3><p class="small muted">Muskelfleischanteil-Formeln nach SchwHKlV</p><div class="formula-callout"><b>Zweipunktverfahren (ZP · Anlage 3):</b><br><code>MFA = 58,10122 − 0,56495 × S + 0,13199 × F</code><p class="small muted" style="margin:.3rem 0 0">Zulässig nur bei ≤ 200 Schlachtungen/Woche im Jahresmittel.</p></div><div class="formula-callout"><b>Sondengeräte (OptiGrade, FOM · Anlage 2):</b><br><code>MFA = 60,98501 − 0,85831 × S + 0,16449 × F</code></div><div class="formula-callout"><b>Ersatzfleischmaß F* (Anlage 2):</b><br><code>F* = 0,95 × G − 3</code><p class="small muted" style="margin:.3rem 0 0">Wenn statt F das Gesamtmaß G erfasst wird.</p></div><button class="btn secondary smallbtn" data-route="calculator">Zum interaktiven Simulator →</button></article><article class="cheatsheet-card" data-sheet-item="schnittfuehrung korrekturfaktoren blatt 1 gehirn augen ohr tierarzt fehler wamme stichfleisch"><h3>✂ Schnittführung & Korrekturfaktoren (Blatt 1)</h3><p class="small muted">Standard-Zurichtung und genehmigte Abweichungen</p><table class="table-compact"><thead><tr><th>Korrekturfaktor</th><th>Mastschwein</th><th>Zuchtschwein</th></tr></thead><tbody><tr><td><b>Gehirn</b></td><td>− 100 g</td><td>− 150 g</td></tr><tr><td><b>Augen + Augenlid</b></td><td>+ 50 g</td><td>+ 50 g</td></tr><tr><td><b>Ohr + Ohrmuschel</b></td><td>+ 200 g</td><td>+ 250 g</td></tr></tbody></table><ul class="anatomy-cut-list" style="padding-left:1.1rem;font-size:.85rem;margin-top:.6rem"><li><b>Was muss raus:</b> Zunge, Geschlechtsorgane, Rückenmark, Brust-/Bauchorgane, Flomen, Nieren, Zwerchfell/-pfeiler, Gehirn.</li><li><b>Zuchtschweine extra:</b> Spitzbeine vorn/hinten; Gesäugeleiste bei Sauen.</li><li><b>Tierarzt darf abschneiden:</b> Verschmutzungen (Öl, Galle, Eiter, Kot), Abszesse, Knochenbrüche.</li><li><b>Häufige Fehler:</b> Zu viel Stichfleisch ab (nur Blutiges erlaubt!), Wamme ab, Spiegelschnitt zu hoch, Brustbein rasiert.</li></ul></article><article class="cheatsheet-card" data-sheet-item="optigrade autofom morgenkontrolle pruefblock toleranz eichung spitze huelse testblock"><h3>⌁ Gerätekontrolle & Sollwerte (Blatt 5 & 7)</h3><p class="small muted">OptiGrade HCP & Auto-FOM III Prüfung</p><ul class="anatomy-cut-list" style="padding-left:1.1rem;font-size:.85rem"><li><b>OptiGrade Spitze:</b> Abmessen auf <b>8,5 mm ± 0,5 mm</b>.</li><li><b>Reflexionshülse:</b> Sollwert <b>150 ± 3</b>.</li><li><b>Testblock (Testschwein):</b> 5 Teststiche von jeder Seite; Sollwerte: <b>8,7 / 60,0</b> und <b>20,2 / 60,0</b> (± 0,5 mm).</li><li><b>Messung:</b> Lichtgeber & Fotozelle beim <b>Herausziehen</b>; linke Hälfte (von uns rechts); Einstich 7 cm ± 1 cm, Ausstich 4 cm ± 0,5 cm.</li><li><b>Auto-FOM III Software:</b> 4 Testschweine – müssen <b>ohne Toleranz</b> bestanden werden.</li><li><b>Auto-FOM III Schallköpfe:</b> Alle 16 Köpfe mit Etalon prüfen: <b>50 mm ± 1 mm</b>. Frontendboard-Tausch nach 3 Jahren.</li></ul></article><article class="cheatsheet-card" data-sheet-item="verwiegung frist tara warmgewicht kaltgewicht 45 minuten protokoll wiegeprotokoll 12 monate endlosformular"><h3>⚖ Verwiegung & Protokollfristen (Blatt 2 & 12)</h3><p class="small muted">Vorschriften nach 1. FlGDV & SchwHKlV</p><ul class="anatomy-cut-list" style="padding-left:1.1rem;font-size:.85rem"><li><b>Verwiegefrist:</b> Spätestens <b>45 Minuten</b> nach dem Stechen. Ablauf: Fleischbeschau → Klassifizierung → Verwiegung → Kühlung. Einzeln, freihängend, ruhig hängend.</li><li><b>Wiegeprotokoll Aufbewahrung:</b> Vom Erstellungstag bis einschließlich das <b>komplette nachfolgende Kalenderjahr</b>.</li><li><b>Unterschrift:</b> Bei Endlosformularen sofort nach der Schlachtung; bei Einzelkarten nach jeder Wiegung.</li><li><b>Klassifizierungsprotokoll:</b> Mindestens <b>6 Monate</b> ab Erstellungstag durch das KU aufbewahren.</li><li><b>Preismeldung:</b> Schweine 80–110 kg, davon mind. <b>60 % pro Woche</b>.</li><li><b>Schlachtnummer:</b> Beide Hälften, Ziffern <b>mindestens 2 cm hoch</b>, essbar/wasser-/feuerfest.</li></ul></article><article class="cheatsheet-card" data-sheet-item="eichamt waagen instandsetzer rotes dreieck zulassung mri ku ausbildung schwellen"><h3>⚑ Eichamt & Qualifikation (Blatt 2, 10, 11)</h3><p class="small muted">MessEV, Instandsetzerzeichen & 2. FlGDV</p><ul class="anatomy-cut-list" style="padding-left:1.1rem;font-size:.85rem"><li><b>Instandsetzerzeichen:</b> <b>Rotes Dreieck</b> (ersetzt Eichsiegel bis zur nächsten Eichung). Oben: Bundesland/Behörde, Mitte: Nummer Instandsetzer, Unten: Datum.</li><li><b>Eichfristen Waagen:</b> Waagen &gt; 3 t: <b>alle 3 Jahre</b>; Waagen &lt; 3 t: <b>alle 2 Jahre</b>. Neue Waagen mit CE: Herstellereichung zulässig. Pfund/Zentner unzulässig; Wiegescheine = amtliche Urkunden.</li><li><b>Klassifizierer-Ausbildung:</b> 3 Monate KU, 5 Tage MRI je Tierart, Prüfung, alle 2 Jahre Wiederholungslehrgang. Erlischt bei 2 Jahren Inaktivität.</li><li><b>Schwellenwerte:</b> Schweine ≥ 500 / Woche; Rinder ≥ 150 / Woche; Schafe ≥ 75 bzw. 50 / Woche.</li></ul></article></div><div class="row" style="margin-top:1rem"><button class="btn primary" data-route="calculator">MFA-Simulator öffnen</button><button class="btn secondary" data-route="practice">Fragen üben</button></div>`;const search=el.querySelector('#sheet-search');search.oninput=e=>{state.cheatsheetSearch=e.target.value.toLowerCase();el.querySelectorAll('[data-sheet-item]').forEach(c=>c.classList.toggle('hide',!c.dataset.sheetItem.includes(state.cheatsheetSearch)))};bindGo(el)}
function mediathekView(el){
  const tab=state.mediathekTab||'autofom';
  const tabs=[
    {id:'autofom',icon:'📡',label:'AutoFOM III'},
    {id:'zp',icon:'📏',label:'ZP-Verfahren'},
    {id:'optigrade',icon:'🔦',label:'OptiGrade MCP'},
    {id:'line',icon:'⏱️',label:'Schlachtlinie & Waage'}
  ];
  let contentHtml='';
  if(tab==='autofom'){
    contentHtml=`
      <section class="card">
        <div class="row between">
          <div>
            <div class="eyebrow">Vollautomatisches Ultraschall-Ganzkörperverfahren</div>
            <h2>Auto-FOM III: Aufbau & Messprinzip</h2>
          </div>
          <span class="tag">16 Ultraschallköpfe</span>
        </div>
        <p>Der Auto-FOM III scannt das unzerlegte, hängende Schwein vor dem Spalten berührungslos mit Ultraschall. Eine permanente Wasserberieselung dient als akustisches Koppelmedium.</p>
        
        <figure class="device-figure">
          <img src="/autofom-diagram.svg" alt="AutoFOM III Systemübersicht mit U-Bügel, 16 Ultraschallköpfen, Splitbox, Control Panel und Teilstückberechnung">
          <figcaption class="small muted" style="margin-top:.5rem;text-align:center">Interaktives Schema: Auto-FOM III Scan-Bügel, Signalweg und Teilstückkalkulation</figcaption>
        </figure>

        <h3>Der Ablauf in 4 einfachen Schritten:</h3>
        <div class="step-list">
          <div class="step-item">
            <div class="step-num">1</div>
            <div>
              <b>Einfahrt in den Scannerbogen</b>
              <p class="small muted" style="margin:0">Das Schlachtschwein hängt an der Transportbahn und fährt hängend (Vorderbeine voran) kontinuierlich durch den U-förmigen Bogen.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">2</div>
            <div>
              <b>Ultraschall & Wasserankopplung</b>
              <p class="small muted" style="margin:0">16 Ultraschall-Prüfköpfe (Transducer) im Bogen senden 2,0–3,5 MHz Impulse. Permanenter Wasserfilm schließt die Luftschicht zwischen Prüfkopf und Schwarte aus.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">3</div>
            <div>
              <b>Vieldimensionale Profilerfassung</b>
              <p class="small muted" style="margin:0">Es werden ca. 200–300 Querschnittsbilder des Rückens, Kamms und Schinkens erzeugt. Signalübergänge (Gewebe-Grenzschichten) ergeben exakte 2D/3D-Speck- und Fleischkonturen.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">4</div>
            <div>
              <b>CaroSecure-Auswertung & 4 Teilstücke</b>
              <p class="small muted" style="margin:0">Der CaroSecure-Industrierechner errechnet den Gesamt-Muskelfleischanteil (MFA) sowie die Gewichte der 4 wertvollen Teilstücke: <b>Schinken, Kotelett (Lachs), Kamm und Bauch</b>.</p>
            </div>
          </div>
        </div>

        <div class="notice small" style="margin-top:1rem">
          <b>Prüfungsrelevante Kontrollwerte (Blatt 7 & 8):</b>
          <ul style="margin:.3rem 0 0;padding-left:1.2rem">
            <li><b>Morgenkontrolle Schallköpfe:</b> Alle 16 Köpfe mit dem Prüfetalon testen – Sollwert: <b>50 mm ± 1 mm</b>.</li>
            <li><b>Softwaretest (CaroSecure):</b> Simulation mit 4 Testschweinen – muss <b>ohne jede Toleranz</b> bestanden werden!</li>
            <li><b>Wartungszyklus:</b> Frontendboards werden nach 3 Jahren vorsorglich getauscht. Splitbox: 10 Eingänge, 1 Ausgang zum Steuerpult.</li>
          </ul>
        </div>

        <div class="row" style="margin-top:1rem">
          <button class="btn secondary" data-lesson="autofom-system">Zur AutoFOM-Lektion</button>
          <button class="btn secondary" data-practice-topic="FOM-Gerät">AutoFOM-Fragen üben</button>
        </div>
      </section>

      <section class="video-card">
        <div class="row between">
          <div>
            <div class="eyebrow">Video-Animation · Frontmatec</div>
            <h3>AutoFOM III an der Schlachtlinie im Einsatz</h3>
          </div>
          <span class="tag gold">Hersteller-Video</span>
        </div>
        <p class="small muted">Originale 3D-Animation des Herstellers Frontmatec: Sieh genau, wie der Schlachtkörper durch den U-Bügel fährt und vermessen wird.</p>
        <div class="video-container" id="player-autofom-1">
          <div class="video-placeholder">
            <p><b>Frontmatec: Animation AutoFOM Scanner</b></p>
            <p class="small muted">Dauer: ca. 1 Min. · Zeigt das Ultraschall-Messprinzip am hängenden Schwein</p>
            <button class="btn primary smallbtn" data-load-video="B-wuu0FDsFM" data-target="player-autofom-1">▶ Video hier abspielen</button>
            <a class="btn ghost smallbtn" href="https://www.youtube.com/watch?v=B-wuu0FDsFM" target="_blank" rel="noopener" style="margin-left:.5rem;color:#fff;border-color:#445">Auf YouTube öffnen ↗</a>
          </div>
        </div>
      </section>

      <section class="video-card">
        <div class="row between">
          <div>
            <div class="eyebrow">Video-Animation · Frontmatec</div>
            <h3>Gesamtablauf: AutoFOM, AutoMarker, Waage & Kühlung</h3>
          </div>
          <span class="tag gold">Hersteller-Video</span>
        </div>
        <p class="small muted">Vollautomatischer Ablauf von der Ultraschall-Erfassung über die automatische Stempelung (AutoMarker) bis zur Verwiegung.</p>
        <div class="video-container" id="player-autofom-2">
          <div class="video-placeholder">
            <p><b>Frontmatec: AutoFom, AutoMarker & Weighing</b></p>
            <p class="small muted">Dauer: ca. 1 Min. · Zeigt den Datentransfer vom Scanner zur Waage und Stempelstation</p>
            <button class="btn primary smallbtn" data-load-video="xnC0_R8SMlQ" data-target="player-autofom-2">▶ Video hier abspielen</button>
            <a class="btn ghost smallbtn" href="https://www.youtube.com/watch?v=xnC0_R8SMlQ" target="_blank" rel="noopener" style="margin-left:.5rem;color:#fff;border-color:#445">Auf YouTube öffnen ↗</a>
          </div>
        </div>
      </section>
    `;
  }else if(tab==='zp'){
    contentHtml=`
      <section class="card">
        <div class="row between">
          <div>
            <div class="eyebrow">Gesetzliches Referenz- & Handmessverfahren</div>
            <h2>ZP-Verfahren (Zweipunktmethode)</h2>
          </div>
          <span class="tag">SchwHKlV Anlage 3</span>
        </div>
        <p>Das ZP-Verfahren ermittelt den Muskelfleischanteil am gespaltenen Schlachtkörper mittels ZP-Lineal (Messschieber) an zwei exakt definierten Stellen.</p>

        <figure class="device-figure">
          <img src="/zp-diagram.svg" alt="ZP-Verfahren Messpunkte mit Speckmaß S über M. glutaeus medius und horizontalem Fleischmaß F zum Wirbelkanal">
          <figcaption class="small muted" style="margin-top:.5rem;text-align:center">Messstellen S und F am M. glutaeus medius (mittlerer Gesäßmuskel)</figcaption>
        </figure>

        <h3>Die Durchführung in 3 einfachen Schritten:</h3>
        <div class="step-list">
          <div class="step-item">
            <div class="step-num">1</div>
            <div>
              <b>Hälfte sauber spalten & Muskel lokalisieren</b>
              <p class="small muted" style="margin:0">Der Schlachtkörper muss mittig durch Wirbelsäule und Brustbein gespalten sein. Im Schinkenbereich wird der Anschnitt des <i>M. glutaeus medius</i> aufgesucht.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">2</div>
            <div>
              <b>Speckmaß S messen (in mm)</b>
              <p class="small muted" style="margin:0">Gemessen wird die <b>dünnste Speckschicht einschließlich Schwarte</b> direkt über dem <i>M. glutaeus medius</i>. Der Schieber wird senkrecht zur Oberfläche angelegt.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">3</div>
            <div>
              <b>Fleischmaß F messen (in mm)</b>
              <p class="small muted" style="margin:0">Gemessen wird die <b>kürzeste horizontale Strecke</b> vom cranialen (kopfwärts gerichteten) Ende des <i>M. glutaeus medius</i> zur <b>dorsalen Kante des Wirbelkanals</b>.</p>
            </div>
          </div>
        </div>

        <div class="formula-callout">
          <b>Gesetzliche ZP-Formel (SchwHKlV Anlage 3):</b><br>
          <code>MFA = 58,10122 − 0,56495 × S + 0,13199 × F</code>
          <p class="small muted" style="margin:.3rem 0 0">Je dicker der Speck (S), desto niedriger der MFA (− 0,56 pro mm). Je kräftiger der Muskel (F), desto höher der MFA (+ 0,13 pro mm).</p>
        </div>

        <div class="notice small" style="margin-top:1rem">
          <b>Gesetzliche Rahmenbedingungen:</b>
          <ul style="margin:.3rem 0 0;padding-left:1.2rem">
            <li><b>Einsatzgrenze:</b> Nur zulässig in Betrieben mit durchschnittlich <b>≤ 200 Schlachtungen pro Woche</b> (im Jahresmittel).</li>
            <li><b>Frist:</b> Messung muss spätestens <b>45 Minuten nach dem Stechen</b> und vor Beginn des Kühlprozesses erfolgen.</li>
          </ul>
        </div>

        <div class="row" style="margin-top:1rem">
          <button class="btn primary" data-route="calculator">Zum interaktiven MFA-Simulator</button>
          <button class="btn secondary" data-lesson="zp">Zur ZP-Lektion</button>
          <button class="btn secondary" data-practice-topic="ZP-Verfahren">ZP-Fragen üben</button>
        </div>
      </section>
    `;
  }else if(tab==='optigrade'){
    contentHtml=`
      <section class="card">
        <div class="row between">
          <div>
            <div class="eyebrow">Optoelektronische Einstichsonde</div>
            <h2>OptiGrade MCP: Einstich & Morgenkontrolle</h2>
          </div>
          <span class="tag">SchwHKlV Anlage 2</span>
        </div>
        <p>Das OptiGrade MCP misst Speck- und Fleischdicke optoelektronisch beim kontrollierten Herausziehen der Sonde aus dem Kotelettstrang.</p>

        <figure class="device-figure">
          <img src="/optigrade-diagram.svg" alt="OptiGrade MCP Einstichwinkel, 90 Grad waagerecht, 7 cm Einstich, 4 cm Ausstich und Kalibrierungswerte">
          <figcaption class="small muted" style="margin-top:.5rem;text-align:center">Messposition an der 2./3. letzten Rippe & optisches Reflexionsprinzip</figcaption>
        </figure>

        <h3>Die Messung in 3 Schritten:</h3>
        <div class="step-list">
          <div class="step-item">
            <div class="step-num">1</div>
            <div>
              <b>Einstichstelle an der linken Hälfte</b>
              <p class="small muted" style="margin:0">Gemessen wird an der <b>linken Hälfte</b> (von hinten gesehen rechts) zwischen der <b>2. und 3. letzten Rippe</b>, 6 bis 8 cm lateral der Spaltlinie.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">2</div>
            <div>
              <b>Waagerechter Einstich im 90°-Winkel</b>
              <p class="small muted" style="margin:0">Sonde exakt rechtwinklig zur Wirbelsäule einstechen. Einstichtiefe <b>7 cm ± 1 cm</b>, Ausstichseite <b>4 cm ± 0,5 cm</b>.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">3</div>
            <div>
              <b>Optische Reflexionsmessung beim Herausziehen</b>
              <p class="small muted" style="margin:0">Diode und Lichtempfänger in der Sondenspitze scannen beim Rückzug das Gewebe. Helles Fettgewebe reflektiert mehr Licht als dunkles Muskelfleisch.</p>
            </div>
          </div>
        </div>

        <div class="formula-callout">
          <b>Gesetzliche Sonden-Formel (SchwHKlV Anlage 2):</b><br>
          <code>MFA = 60,98501 − 0,85831 × S + 0,16449 × F</code>
          <p class="small muted" style="margin:.3rem 0 0">Wird das Ersatzfleischmaß F* verwendet, gilt: <code>F* = 0,95 × G − 3</code>.</p>
        </div>

        <div class="notice small" style="margin-top:1rem">
          <b>Prüfungsrelevante Morgenkontrolle (Blatt 5 & 6):</b>
          <ul style="margin:.3rem 0 0;padding-left:1.2rem">
            <li><b>Sondenspitze:</b> Mit Schublehre nachmessen: <b>8,5 mm ± 0,5 mm</b>.</li>
            <li><b>Reflexionshülse:</b> Prüfwert: <b>150 ± 3</b>.</li>
            <li><b>Prüfblock (Testschwein):</b> 5 Stiche je Seite; Sollwerte: <b>8,7 / 60,0 mm</b> und <b>20,2 / 60,0 mm</b> (Toleranz: <b>± 0,5 mm</b>).</li>
          </ul>
        </div>

        <div class="row" style="margin-top:1rem">
          <button class="btn secondary" data-lesson="optigrade-mcp">Zur OptiGrade-Lektion</button>
          <button class="btn secondary" data-route="calculator">MFA-Simulator</button>
        </div>
      </section>
    `;
  }else if(tab==='line'){
    contentHtml=`
      <section class="card">
        <div class="row between">
          <div>
            <div class="eyebrow">Gesetzliche Schlachtkette & Zeitgrenzen</div>
            <h2>Die Schlachtlinie: Vom Stechen bis zur Kühlung</h2>
          </div>
          <span class="tag">1. FlGDV & SchwHKlV</span>
        </div>
        <p>Reihenfolge, Wiegevorschriften und eichamtliche Anforderungen sind strikt durch Bundesgesetze geregelt.</p>

        <div class="step-list">
          <div class="step-item">
            <div class="step-num">1</div>
            <div>
              <b>Stechen & Entbluten</b>
              <p class="small muted" style="margin:0"><b>Beginn der gesetzlichen 45-Minuten-Frist!</b> Alle nachfolgenden Schritte bis zur Verwiegung müssen innerhalb dieser Frist erfolgen.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">2</div>
            <div>
              <b>Brühen, Entborsten & Abflämmen</b>
              <p class="small muted" style="margin:0">Hygienische Vorbereitung. Bei AutoFOM-Betrieben wird der Ganzkörperscan nach dem Entborsten durchgeführt.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">3</div>
            <div>
              <b>Ausweiden & amtliche Fleischbeschau</b>
              <p class="small muted" style="margin:0">Organe, Flomen und Nieren werden entnommen. Tierarzt führt die amtliche Schlachttier- und Fleischuntersuchung durch.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">4</div>
            <div>
              <b>Klassifizierung</b>
              <p class="small muted" style="margin:0">Erfassung des Muskelfleischanteils (AutoFOM, OptiGrade oder ZP-Verfahren) und Kennzeichnung der Handelsklasse.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">5</div>
            <div>
              <b>Verwiegung (Warmgewicht)</b>
              <p class="small muted" style="margin:0">Muss <b>spätestens 45 Minuten nach dem Stechen</b> und <b>vor Beginn der Kühlung</b> erfolgen. Der Schlachtkörper muss frei und ruhig an der Rohrbahnwaage hängen.</p>
            </div>
          </div>
          <div class="step-item">
            <div class="step-num">6</div>
            <div>
              <b>Schnellabkühlung & Kühlraum</b>
              <p class="small muted" style="margin:0">Erst nach Verwiegung und Protokollierung darf der aktive Kühlprozess gestartet werden (Gewichtsverlust durch Verdunstung = Kaltgewicht).</p>
            </div>
          </div>
        </div>

        <div class="notice small" style="margin-top:1rem">
          <b>Eichrecht & Prüfungsregeln (Blatt 2 & 10):</b>
          <ul style="margin:.3rem 0 0;padding-left:1.2rem">
            <li><b>Eichfristen:</b> Waagen unter 3 Tonnen Höchstlast: <b>alle 2 Jahre</b>; Waagen über 3 Tonnen: <b>alle 3 Jahre</b>.</li>
            <li><b>Instandsetzerzeichen (Rotes Dreieck):</b> Ersetzt das Eichsiegel vorübergehend nach einer Reparatur bis zur nächsten amtlichen Nacheichung.</li>
            <li><b>Protokoll-Aufbewahrung:</b> Wiegeprotokoll: bis zum Ende des <b>nachfolgenden Kalenderjahres</b>. Klassifizierungsprotokoll: mind. <b>6 Monate</b>.</li>
          </ul>
        </div>

        <div class="row" style="margin-top:1rem">
          <button class="btn secondary" data-lesson="weighing">Zur Verwiegungs-Lektion</button>
          <button class="btn secondary" data-practice-topic="Verwiegung">Verwiegungs-Fragen üben</button>
        </div>
      </section>

      <section class="video-card">
        <div class="row between">
          <div>
            <div class="eyebrow">Video-Animation · Frontmatec</div>
            <h3>Rohrbahnwaage & Übergang zum Kühlhaus</h3>
          </div>
          <span class="tag gold">Hersteller-Video</span>
        </div>
        <p class="small muted">Einblick in die kontinuierliche Verwiegung am Hängeförderer und die automatische Ausschleusung in die Kühlkammern.</p>
        <div class="video-container" id="player-line-1">
          <div class="video-placeholder">
            <p><b>Frontmatec: Weighing Scale and Chill Room</b></p>
            <p class="small muted">Dauer: ca. 1 Min. · Zeigt die Freihängung an der Bandwaage</p>
            <button class="btn primary smallbtn" data-load-video="mUiOONO8ZEY" data-target="player-line-1">▶ Video hier abspielen</button>
            <a class="btn ghost smallbtn" href="https://www.youtube.com/watch?v=mUiOONO8ZEY" target="_blank" rel="noopener" style="margin-left:.5rem;color:#fff;border-color:#445">Auf YouTube öffnen ↗</a>
          </div>
        </div>
      </section>
    `;
  }
  el.innerHTML=head('Geräte & Praxis','🎬 Geräte-Mediathek & Videos','Interaktive Funktionsschemata, Video-Animationen und prüfungsrelevante Kontrollschritte.')+
    `<div class="mediathek-tabs">
      ${tabs.map(t=>`<button class="mediathek-tab ${t.id===tab?'active':''}" data-mediathek-tab="${t.id}">${t.icon} ${t.label}</button>`).join('')}
    </div>
    <div id="mediathek-content">${contentHtml}</div>`;
  el.querySelectorAll('[data-mediathek-tab]').forEach(btn=>{
    btn.onclick=()=>{
      state.mediathekTab=btn.dataset.mediathekTab;
      mediathekView(el);
    };
  });
  el.querySelectorAll('[data-load-video]').forEach(btn=>{
    btn.onclick=()=>{
      const vid=btn.dataset.loadVideo;
      const targetId=btn.dataset.target;
      const host=el.querySelector('#'+targetId);
      if(host){
        host.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(vid)}?autoplay=1&rel=0" title="YouTube video player" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`;
      }
    };
  });
  el.querySelectorAll('[data-practice-topic]').forEach(btn=>{
    btn.onclick=()=>{
      state.filter=btn.dataset.practiceTopic;
      startPractice(btn.dataset.practiceTopic,5,'text');
    };
  });
  bindGo(el);
}

async function trainerLoad(){state.trainer=await api('/trainer/learners')}
async function trainerView(el){try{await trainerLoad()}catch(e){el.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;return}const data=state.trainer;const names=data.learners.filter(l=>l.name.toLowerCase().includes((state.trainerSearch||'').toLowerCase()));const avg=data.learners.length?Math.round(data.learners.reduce((s,l)=>s+l.progress.accuracy,0)/data.learners.length):0;const needs=data.learners.filter(l=>Object.values(l.progress.topic||{}).some(x=>x.answered>=3&&pct(x.correct,x.answered)<60)).length;el.innerHTML=`<div class="section-head"><div><div class="eyebrow">Ausbilderbereich${state.data.demo?' · Beispieldaten':''}</div><h1>Meine Lerngruppe</h1><p>Konten in ${esc(state.data.group||'deiner Gruppe')}. Individuelle Lerndaten sehen nur die zugehörigen Ausbilderkonten.</p></div>${data.groups.length>1?`<select id="trainer-group" class="search" style="width:auto">${data.groups.map(g=>`<option ${g===state.data.group?'selected':''}>${esc(g)}</option>`).join('')}</select>`:''}</div><div class="grid three"><article class="card"><div class="metric">${data.learners.length}</div><div class="metric-label">Lernende</div></article><article class="card"><div class="metric">${avg}%</div><div class="metric-label">Ø Antwortgenauigkeit</div></article><article class="card"><div class="metric">${needs}</div><div class="metric-label">brauchen Übungsbegleitung</div></article></div><section class="card" style="margin-top:1rem"><div class="row between"><h2>Lernende</h2><div class="row" style="gap:.5rem"><button class="btn secondary smallbtn" id="export-group-csv">📊 Gruppenbericht (CSV)</button><input class="search" id="learner-search" placeholder="Name suchen" value="${esc(state.trainerSearch||'')}" style="max-width:240px"></div></div><div class="stack" style="margin-top:.8rem">${names.length?names.map(l=>`<article class="card tight" data-learner-card="${esc(l.name.toLowerCase())}"><div class="learner-row"><div class="learner-main"><div class="row between"><b>${esc(l.name)}</b>${l.demo?'<span class="tag gold">Beispieldaten</span>':''}</div><div class="row between small"><span>${l.progress.lessons} Lektionen · ${l.progress.answered} Antworten</span><span>${l.progress.accuracy}% richtig</span></div><div class="progress-track" style="margin:.5rem 0"><div class="progress-fill" style="width:${l.progress.accuracy}%"></div></div><div class="row between small muted"><span>Zuletzt aktiv: ${esc(l.progress.lastActive)}</span><span>${l.progress.practical.length} Praxis-Checks</span></div></div><button class="btn secondary smallbtn" data-learner="${l.id}">Fortschritt ansehen</button></div></article>`).join(''):'<p class="muted">Noch keine Lernenden in dieser Gruppe. Lade eine Person mit einem Einladungscode ein.</p>'}</div></section><section class="card" style="margin-top:1rem"><h2>Einladung erstellen</h2><p class="small muted">Erstelle einen Einmal-Code für ein echtes lokales Lernkonto. Einladungen werden nicht per E-Mail versandt.</p><form id="invite-form" class="grid two"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>E-Mail (optional)</label><input name="email" type="email"></div><button class="btn primary">Code erstellen</button><div id="invite-output"></div></form>${data.invitations.length?`<div class="lesson-list" style="margin-top:.8rem">${data.invitations.map(i=>`<div class="lesson-item"><div><b>${esc(i.name)}</b><small>${esc(i.status)} · ${esc(i.group)}</small></div><span class="tag">${i.status==='Offen'?esc(i.code):'Verwendet'}</span></div>`).join('')}</div>`:''}</section><div class="notice small" style="margin-top:1rem">${state.data.demo?'Die angezeigten Lernenden sind als Beispieldaten markiert. Demo-Fortschritt ist keine reale Lernhistorie.':'Passwortgeschützte lokale Konten · Trainerzugriff wird serverseitig auf die eigene Gruppe beschränkt.'}</div>`;
el.querySelector('#export-group-csv')?.addEventListener('click',async()=>{try{const exp=await api('/trainer/export');const rows=[['Name','Gruppe','Lektionen','Antworten','Richtig','Genauigkeit %','Praxis-Checks','Zuletzt aktiv'],...(exp.learners||[]).map(l=>[`"${(l.name||'').replace(/"/g,'""')}"`,`"${(exp.group||'').replace(/"/g,'""')}"`,l.progress?.lessons??0,l.progress?.answered??0,l.progress?.correct??0,l.progress?.accuracy??0,(l.progress?.practical||[]).length,`"${(l.progress?.lastActive||'').replace(/"/g,'""')}"`])];const csvContent='\uFEFF'+rows.map(r=>r.join(';')).join('\r\n');const blob=new Blob([csvContent],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`lerngruppe-${(exp.group||'export').toLowerCase().replace(/[^a-z0-9]/g,'-')}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Gruppenbericht exportiert')}catch(err){toast(err.message)}});
el.querySelector('#learner-search').oninput=e=>{const term=e.target.value.toLowerCase();el.querySelectorAll('[data-learner-card]').forEach(card=>card.classList.toggle('hide',!card.dataset.learnerCard.includes(term)))};el.querySelectorAll('[data-learner]').forEach(b=>b.onclick=()=>{state.trainerLearner=state.trainer.learners.find(l=>l.id===b.dataset.learner);state.route='learnerDetail';render()});el.querySelector('#invite-form').onsubmit=async e=>{e.preventDefault();const out=await api('/trainer/invite','POST',Object.fromEntries(new FormData(e.target)));const link=`${window.location.origin}/#invite=${out.code}`;const qr=generateQrSvg(link,160);el.querySelector('#invite-output').innerHTML=`<div class="invite-share-card"><div class="eyebrow">Einladungscode für Lernende</div><div class="invite-big-code">${esc(out.code)}</div><div class="invite-qr-wrap">${qr}</div><p class="small muted">Einmalig gültig für <b>${esc(state.data.group)}</b>. Mit Smartphone-Kamera scannen oder Code eingeben.</p><button class="btn primary smallbtn" id="copy-invite-link">📋 Direktlink kopieren</button></div>`;el.querySelector('#copy-invite-link')?.addEventListener('click',()=>{navigator.clipboard?.writeText(link).then(()=>toast('Direktlink kopiert!')).catch(()=>toast(`Link: ${link}`))});await trainerLoad();trainerView(el)};el.querySelector('#trainer-group')?.addEventListener('change',async e=>{await api('/trainer/group','POST',{group:e.target.value});await refresh();trainerView(el)})}
function trainerDetailView(el){const l=state.trainerLearner;if(!l){state.route='learners';return trainerView(el)}const allTasks=["Arbeitsplatz vorbereiten","Messpunkte sicher finden","Waage korrekt bedienen","Ergebnis dokumentieren","Referenzpräsentation und Schnittführung prüfen","Morgenkontrolle am Betriebsgerät durchführen","Softwareversionen und Prüfergebnisse abgleichen","Messfehler erkennen und korrekt reagieren"];const topic=TOPICS.map(t=>{const d=l.progress.topic[t]||{answered:0,correct:0};return `<div class="topic-line" style="margin:.8rem 0"><span>${esc(t)}</span><div class="progress-track"><div class="progress-fill" style="width:${pct(d.correct,d.answered)}%"></div></div><span>${d.answered?pct(d.correct,d.answered)+'%':'—'}</span></div>`}).join('');el.innerHTML=`<button class="btn ghost smallbtn" id="detail-back">← Zur Lerngruppe</button>${head('Lernendenfortschritt',esc(l.name),`${state.data.group} · zuletzt aktiv: ${esc(l.progress.lastActive)}`)}${l.demo?'<div class="notice warning small">Beispielprofil · keine echte Lernhistorie</div>':''}<div class="grid three" style="margin-top:1rem"><article class="card"><div class="metric">${l.progress.lessons}</div><div class="metric-label">Abgeschlossene Lektionen</div></article><article class="card"><div class="metric">${l.progress.accuracy}%</div><div class="metric-label">Antwortgenauigkeit (${l.progress.correct}/${l.progress.answered})</div></article><article class="card"><div class="metric">${l.progress.answered}</div><div class="metric-label">Beantwortete Fragen</div></article></div><section class="card" style="margin-top:1rem"><h2>Themenübersicht</h2>${topic}</section><section class="card" style="margin-top:1rem"><h2>Praktische Aufgaben bestätigen</h2><p class="small muted">Nur nach eigener Beobachtung im Betrieb bestätigen. Online-Übungen zählen nicht.</p>${allTasks.map(item=>`<div class="row between" style="padding:.7rem 0;border-bottom:1px solid var(--line)"><span>${esc(item)}</span>${l.progress.practical.includes(item)?'<span class="tag">Bestätigt</span>':`<button class="btn secondary smallbtn" data-practical="${esc(item)}">Bestätigen</button>`}</div>`).join('')}</section>`;el.querySelector('#detail-back').onclick=()=>{state.route='learners';render()};el.querySelectorAll('[data-practical]').forEach(b=>b.onclick=async()=>{await api('/trainer/practical','POST',{learnerId:l.id,item:b.dataset.practical});await trainerLoad();state.trainerLearner=state.trainer.learners.find(x=>x.id===l.id);trainerDetailView(el);toast('Praxisaufgabe bestätigt')})}

